window.DONNEES = {"jeu":{"titre":"Bismillah c'est les ténèbres","confianceDepart":50,"effets":{"demasque":8,"sansPreuve":-5,"rate":-12,"accuseATort":-25},"preuvesRequises":2,"jours":[{"numero":1,"fichier":"data/jour1.json"},{"numero":2,"fichier":"data/jour2.json"},{"numero":3,"fichier":"data/jour3.json"},{"numero":4,"fichier":"data/jour4.json"},{"numero":5,"fichier":"data/jour5.json"}],"peurNuit":5,"seuilReserve":50,"seuilAllie":25},"jours":{"1":{"jour":1,"titre":"Lundi. La veille du blocus.","intro":["On est lundi. Demain, mardi, à l'aube, le lycée Jean-Moulin sera bloqué. Les poubelles à traîner devant la grille sont repérées, la banderole attend au fond d'un casier. Tout est prêt.","Ce matin, Inès a reçu un message anonyme : « Y a deux keufs chez vous. Ils se font passer pour des élèves. Ils veulent savoir qui organise. »","Tu as jusqu'à ce soir pour les trouver. Chaque question te coûte du temps. Et si tu accuses quelqu'un à tort, c'est toi que plus personne ne croira."],"actions":11,"heureDebut":8,"minutesParAction":44,"nbInfiltres":2,"zones":[{"id":"entree","nom":"Entrée","decor":"Grille verte, sacs sur l'épaule, la CPE qui compte les retards."},{"id":"cantine","nom":"Cantine","decor":"Odeur de frites et de javel. Plateaux qui claquent."},{"id":"fumoir","nom":"Fumoir","decor":"Le coin derrière le gymnase, là où les pions ne vont jamais."},{"id":"gymnase","nom":"Gymnase","decor":"Parquet qui grince, filets troués, odeur de caoutchouc."},{"id":"cdi","nom":"CDI","decor":"Silence, néons, un ordi sur deux qui marche."}],"indices":{"ines_t3":{"texte":"Inès : la T4 a fermé à la rentrée. Il ne reste que trois terminales générales, T1, T2, T3.","type":"info"},"ines_garnier":{"texte":"Inès : un vrai élève sait quels profs sont partis ou ont été remplacés cette année.","type":"info"},"kenzo_t4":{"texte":"{kenzo} dit être en « Terminale 4 », chez les STMG.","type":"info","sur":"kenzo"},"kenzo_vape":{"texte":"La vape de {kenzo} n'a jamais été allumée : le film plastique est encore sur l'embout.","type":"suspect","sur":"kenzo"},"kenzo_blocus":{"texte":"{kenzo} veut savoir combien vous êtes à organiser le blocus.","type":"suspect","sur":"kenzo"},"kenzo_aveu":{"texte":"Coincé sur la T4, Kenzo corrige aussitôt en « T3 ». Personne ne se trompe sur sa propre classe.","type":"suspect","sur":"kenzo"},"dylan_oreillette":{"texte":"{dylan} dit écouter un podcast dans son seul écouteur, mais rien ne sort.","type":"suspect","sur":"dylan"},"dylan_alliance":{"texte":"{dylan} a une trace d'alliance pâle à l'annulaire gauche.","type":"suspect","sur":"dylan"},"dylan_garnier":{"texte":"{dylan} dit avoir Mme Garnier en maths, en 1re B.","type":"info","sur":"dylan"},"moussa_garnier":{"texte":"{moussa} : Mme Garnier est partie à la retraite en juin dernier. Les 1re B ont M. Haddad.","type":"info"},"dylan_questions":{"texte":"{moussa} : le mec du gymnase aux baskets blanches lui a demandé qui fait partie du comité.","type":"suspect","sur":"dylan"},"yanis_nouveau":{"texte":"{yanis} est arrivé il y a deux semaines. Personne ne le connaît.","type":"suspect","sur":"yanis"},"yanis_lyon":{"texte":"Yanis est arrivé de Lyon il y a deux semaines : sa mère a été mutée ici.","type":"innocent","sur":"yanis"},"sarah_questions":{"texte":"{sarah} pose beaucoup de questions sur le blocus et prend des notes.","type":"suspect","sur":"sarah"},"sarah_journal":{"texte":"{sarah} écrit pour « Le Moulin », le journal du lycée. Elle a montré ses anciens articles signés.","type":"innocent","sur":"sarah"},"lucas_baskets":{"texte":"Lucas a aussi des baskets blanches neuves, comme Dylan. Les siennes sont déjà abîmées.","type":"suspect","sur":"lucas"},"lucas_anniv":{"texte":"{lucas} : ses baskets sont un cadeau d'anniversaire, offert samedi par sa grand-mère.","type":"innocent","sur":"lucas"},"chloe_parano":{"texte":"{chloe} est persuadée que {yanis} est un flic, « parce qu'il dit bonjour à la CPE ».","type":"info"},"dylan_aveu":{"texte":"Coincé sur Mme Garnier, {dylan} n'a pas su nommer son « remplaçant ».","type":"suspect","sur":"dylan"},"malik_sarah":{"texte":"{sarah} : le nouveau arrivé ce matin lui a demandé l'heure du blocus et si c'est Inès qui gère.","type":"suspect","sur":"malik"},"lucas_haddad":{"texte":"{lucas} connaît son prof de maths : M. Haddad, qui remplace Mme Garnier.","type":"innocent","sur":"lucas"},"yanis_cpe":{"texte":"{yanis} dit bonjour à la CPE parce qu'elle gère son dossier de bourse.","type":"innocent","sur":"yanis"},"malik_nouveau":{"texte":"{malik} est arrivé ce matin. Personne ne le connaît, et il demande l'heure du blocus à tout le monde.","type":"suspect","sur":"malik"},"malik_pasteur":{"texte":"{malik} dit avoir été renvoyé du lycée Pasteur pour une bagarre. Personne ici ne peut le confirmer.","type":"suspect","sur":"malik"},"malik_livraison":{"texte":"Malik : il demande l'heure parce qu'il livre des colis avec son oncle de 6h à 8h.","type":"innocent","sur":"malik"},"malik_t2":{"texte":"{malik} dit avoir été mis en T2, et montre le papier de la vie scolaire.","type":"innocent","sur":"malik"},"lucas_dylan":{"texte":"Lucas est en 1re B depuis septembre et n'a jamais vu Dylan en cours, qui dit être dans la même classe.","type":"suspect","sur":"dylan"},"chloe_vape":{"texte":"{chloe} : {kenzo} fait semblant de fumer avec eux. Sa vape ne fait même pas de vapeur.","type":"suspect","sur":"kenzo"},"moussa_malik":{"texte":"{moussa} : le nouveau, à l'entrée, lui a demandé à quelle heure ça commence.","type":"suspect","sur":"malik"}},"pnj":[{"id":"ines","nom":"Inès","zone":"entree","infiltre":false,"allie":true,"posture":"Distribue des tracts pliés en quatre, l'œil partout.","sprite":{"peau":"#a8704a","cheveux":"long","couleurCheveux":"#1b1210","haut":"#5a2a6b","accessoires":["boucles"]},"observer":{"texte":"Ta pote depuis la sixième. Cernes de quelqu'un qui a dormi trois heures. Elle tient le planning du blocus dans sa tête et nulle part ailleurs."},"questions":[{"id":"q1","q":"Tu as une idée de qui c'est ?","r":"Non. Mais un flic, ça connaît pas le lycée de l'intérieur. Les classes, les profs, les histoires. Teste-les là-dessus. Tiens : ils ont fermé la T4 à la rentrée. Nous, on le sait. Eux, peut-être pas.","indice":"ines_t3"},{"id":"q2","q":"Et pour ceux qui disent être en première ?","r":"Parle-leur de leurs profs. Pas juste des noms, ça s'apprend. Qui est parti, qui est nouveau, qui est relou. Ça, il faut l'avoir vécu.","indice":"ines_garnier"},{"id":"q3","q":"Et si je me trompe ?","r":"Alors on aura viré un des nôtres la veille du blocus. Et plus personne t'écoutera. Pas de preuve, pas d'accusation. Sérieux.","gratuit":true}]},{"id":"malik","nom":"{malik}","zone":"entree","infiltre":false,"posture":"Sac neuf sur l'épaule, plan du lycée à la main. Il regarde partout.","sprite":{"peau":"#8a5a3c","cheveux":"court","couleurCheveux":"#100b08","haut":"#3d6b4f","accessoires":[]},"observer":{"texte":"Personne ne le connaît. Sac neuf, chaussures neuves, un plan du lycée imprimé. Il a demandé l'heure du blocus à deux personnes en dix minutes.","indice":"malik_nouveau"},"questions":[{"id":"q1","q":"T'es nouveau ?","r":"Arrivé ce matin. Je viens de Pasteur, ils m'ont viré pour une histoire de bagarre. Je connais personne ici.","indice":"malik_pasteur"},{"id":"q2","q":"Pourquoi tu demandes l'heure du blocus partout ?","apres":["obs"],"r":"Parce que je bosse. Je livre des colis avec mon oncle, de 6h à 8h. Si vous bloquez à 7h, je peux pas venir. À 8h, je suis là. Tu crois que ça me fait plaisir de demander ?","indice":"malik_livraison"},{"id":"q3","q":"T'es dans quelle terminale ?","requiert":"ines_t3","r":"Ils m'ont mis en T2. Enfin, je crois. J'ai pas encore vu la salle, j'ai juste un papier de la vie scolaire.","indice":"malik_t2"}],"fin":{"accuseATort":"Le lendemain, {malik} vient quand même. Il ne parle plus à personne, et plus personne ne lui parle. Seul, sans personne à qui se confier. Exactement le genre d'élève que d'autres savent repérer."}},{"id":"kenzo","nom":"{kenzo}","zone":"fumoir","sprite":{"peau":"#e0b190","cheveux":"casquette","couleurCheveux":"#5b3a22","haut":"#c7c7c7","accessoires":["vape"]},"posture":"Adossé au mur du fumoir, une vape à la main. Il rit avec tout le monde.","observer":{"texte":"Casquette à l'envers, sweat gris un peu grand. Il tire sur sa vape de temps en temps. Tu regardes mieux : le film plastique est encore sur l'embout. Elle n'a jamais servi.","indice":"kenzo_vape"},"questions":[{"id":"q1","q":"T'es dans quelle classe, toi ?","r":"Terminale 4. Les STMG. Tranquille.","indice":"kenzo_t4"},{"id":"q2","q":"Tu viens demain ?","r":"Wesh, bismillah c'est les ténèbres, frérot ! Je serai là, sur la tête de ma mère. Vous êtes combien à organiser, au fait ? Que je sache à qui parler si y a un souci.","indice":"kenzo_blocus"},{"id":"q3","q":"Tu écoutes quoi en ce moment ?","r":"Du Werenoi, du Ninho. Comme tout le monde, quoi."},{"id":"q4","q":"La T4 ? Elle a fermé cette année.","requiert":"ines_t3","apres":["q1"],"r":"Un blanc. « Ouais, non... T3. Je voulais dire T3. » Il tire sur sa vape, qui ne fume pas.","indice":"kenzo_aveu"}],"fin":{"demasque":"Devant tout le fumoir, {kenzo} sourit, puis range sa vape dans une poche intérieure. Une carte tricolore dépasse. Il part sans courir. La T4 a fermé à la rentrée : personne ne le lui avait dit.","sansPreuve":"Tu l'accuses, il éclate de rire : « Moi, un keuf ? T'es sérieux ? » Sans preuve, le fumoir rigole avec lui. Il est encore là demain.","rate":"Personne ne l'a soupçonné. Demain à 7h, une voiture banalisée attend déjà devant la grille, à l'heure exacte du blocus."},"grade":"Brigadier Laurent, 34 ans","infiltre":true},{"id":"yanis","nom":"{yanis}","zone":"cdi","infiltre":false,"posture":"Seul à une table, casque sur les oreilles, révise un contrôle.","sprite":{"peau":"#6b4530","cheveux":"boucle","couleurCheveux":"#120c0a","haut":"#24486b","accessoires":["lunettes"]},"observer":{"texte":"Personne ne s'assoit avec lui. Tu ne l'as jamais vu avant la rentrée des vacances. Il a l'air d'être là depuis deux semaines, pas plus.","indice":"yanis_nouveau"},"questions":[{"id":"q1","q":"T'es nouveau ?","r":"Ouais, deux semaines. On a déménagé de Lyon, ma mère a eu une mutation. Ici je connais personne, c'est la galère.","indice":"yanis_lyon"},{"id":"q2","q":"C'est qui ton prof principal ?","r":"M. Benali. Il est cool, il m'a laissé finir mon contrôle de physique à la récré parce que j'étais pas là le premier jour."},{"id":"q3","q":"Tu viens au blocus demain ?","r":"Je sais pas... Si je me fais choper le premier mois, ma mère me tue. Mais je suis d'accord avec vous, hein."},{"id":"q4","q":"Il paraît que tu dis bonjour à la CPE ?","requiert":"chloe_parano","r":"Ben oui, c'est elle qui gère mon dossier de bourse. À Lyon on dit bonjour aux gens, c'est tout. Pourquoi, c'est interdit ici ?","indice":"yanis_cpe"}],"fin":{"accuseATort":"Le lendemain, quelqu'un a écrit « BALANCE » sur le casier de {yanis}. Il mange seul au CDI. Deux semaines plus tard, il change de lycée. Personne ne lui a demandé pardon."}},{"id":"sarah","nom":"{sarah}","zone":"cdi","infiltre":false,"posture":"Carnet ouvert, stylo dans la bouche, écoute toutes les conversations.","sprite":{"peau":"#f0c8a8","cheveux":"chignon","couleurCheveux":"#a3502a","haut":"#2d5a3a","accessoires":["lunettes"]},"observer":{"texte":"Elle note tout ce qu'elle entend. Les dates, les heures, les noms. Elle t'a vu arriver et a tourné une page.","indice":"sarah_questions"},"questions":[{"id":"q1","q":"Tu notes quoi, là ?","r":"Je fais un papier sur le blocus pour Le Moulin, le journal du lycée. Tiens, regarde, c'est moi qui ai écrit celui sur la cantine l'an dernier. Le scandale des lasagnes.","indice":"sarah_journal"},{"id":"q2","q":"Pourquoi tu poses autant de questions ?","r":"Parce que c'est mon taf ? Si personne ne raconte ce qui se passe demain, c'est la version du proviseur qui restera."},{"id":"q3","q":"T'as remarqué quelqu'un de bizarre ?","r":"Le nouveau, arrivé ce matin. Il m'a demandé à quelle heure on bloque, et si c'est Inès qui gère. Il a pas l'air de savoir où sont les salles.","indice":"malik_sarah"}],"fin":{"accuseATort":"{sarah} est exclue du groupe du blocus. Son article ne sort jamais. Dans le journal local, la seule version publiée est celle de la préfecture."}},{"id":"dylan","nom":"{dylan}","zone":"gymnase","sprite":{"peau":"#d9a27a","cheveux":"rase","couleurCheveux":"#2a1a12","haut":"#1f2b5c","accessoires":["oreillette"]},"posture":"Fait des passes de basket tout seul, très appliqué.","observer":{"texte":"Survêtement de marque, baskets blanches impeccables. Quand il récupère le ballon, tu vois une bande de peau plus claire autour de son annulaire gauche. Un seul écouteur, à droite.","indice":"dylan_alliance"},"questions":[{"id":"q1","q":"T'es en quelle classe ?","r":"1re B. Avec Mme Garnier en maths. Elle est sévère, mais ça va.","indice":"dylan_garnier"},{"id":"q2","q":"Elles sont neuves, tes baskets ?","apres":["obs"],"r":"Ouais. J'aime bien quand c'est propre. Je fais gaffe, c'est tout."},{"id":"q3","q":"Tu écoutes quoi ?","apres":["obs"],"r":"« Un podcast. » Il touche son écouteur droit. Tu tends l'oreille : rien ne sort.","indice":"dylan_oreillette"},{"id":"q4","q":"Garnier ? Elle est à la retraite depuis juin.","requiert":"moussa_garnier","apres":["q1"],"r":"Il rattrape le ballon et le garde. « Ouais, je sais. Je voulais dire... celui qui la remplace. » Il ne trouve pas le nom.","indice":"dylan_aveu"}],"fin":{"demasque":"{dylan} regarde vers la grille, porte la main à son écouteur et murmure quelque chose. Il ramasse son sac neuf et sort par le portail des profs. Personne ne l'a jamais vu en cours.","sansPreuve":"Tu l'accuses. Il hausse les épaules : « T'es parano, frère. » Sans preuve, les autres te regardent de travers.","rate":"Le soir même, une liste de prénoms circule dans un commissariat. Le tien est dessus. Celui d'Inès est souligné deux fois."},"grade":"Gardien de la paix Morel, 29 ans","infiltre":true},{"id":"moussa","nom":"{moussa}","zone":"cantine","infiltre":false,"posture":"Négocie un deuxième dessert avec la dame de la cantine.","sprite":{"peau":"#4a2e20","cheveux":"court","couleurCheveux":"#0e0a08","haut":"#b33a2a","accessoires":[]},"observer":{"texte":"Le mec qui connaît tout le monde. Délégué de sa classe depuis trois ans, il a un surnom pour chaque prof et chaque pion."},"questions":[{"id":"q1","q":"Tu connais Mme Garnier ?","apres":["dylan:q1"],"r":"Garnier ? Partie à la retraite en juin, frérot. Y a eu un pot, elle a pleuré, miskina. Les 1re B ont Haddad maintenant. Pourquoi ?","indice":"moussa_garnier"},{"id":"q2","q":"Quelqu'un t'a parlé du blocus ?","r":"Deux mecs. Celui du gymnase, avec les baskets toutes blanches, m'a demandé qui fait partie du comité. Et le nouveau, à l'entrée, m'a demandé à quelle heure ça commence. Les deux, je les connais pas, wallah.","indice":"dylan_questions","aussi":["moussa_malik"]},{"id":"q3","q":"Et {lucas}, ses baskets neuves ?","r":"C'est son anniv' samedi, j'y étais ! Sa grand-mère lui a offert. Il nous a saoulés avec toute la soirée.","indice":"lucas_anniv","requiert":"lucas_baskets"}],"fin":{"accuseATort":"{moussa} n'est plus délégué. Il ne parle plus à personne du blocus, ni de rien d'autre. Le lycée a perdu sa mémoire."}},{"id":"chloe","nom":"{chloe}","zone":"fumoir","infiltre":false,"posture":"Assise sur une poubelle, regarde tout le monde comme un suspect.","sprite":{"peau":"#f2d0b5","cheveux":"capuche","couleurCheveux":"#151515","haut":"#111111","accessoires":["boucles"]},"observer":{"texte":"Sweat noir, capuche sur la tête, eyeliner épais. Elle a déjà fait deux blocus et une garde à vue. Elle ne fait confiance à personne, toi compris."},"questions":[{"id":"q1","q":"T'as repéré quelqu'un ?","r":"Le nouveau, {yanis}. Il dit bonjour à la CPE. Qui dit bonjour à la CPE ? C'est un flic, je te dis.","indice":"chloe_parano"},{"id":"q2","q":"Et le mec à la casquette, à côté ?","r":"{kenzo} ? Il est relou mais il fume avec nous. Enfin... il fait genre. Sa vape fait même pas de vapeur, maintenant que tu le dis.","indice":"chloe_vape"},{"id":"q3","q":"Pourquoi tu te méfies de tout le monde ?","r":"Parce qu'au dernier blocus, quelqu'un a balancé. Trois potes en garde à vue. Depuis, je regarde tout le monde. Même toi."}],"fin":{"accuseATort":"{chloe} ne revient pas au fumoir. Le jour du blocus, elle reste chez elle. « Vous vous bouffez entre vous, ils ont même pas besoin de bosser », écrit-elle sur le groupe avant de le quitter."}},{"id":"lucas","nom":"{lucas}","zone":"gymnase","sprite":{"peau":"#e8b896","cheveux":"court","couleurCheveux":"#c49a4a","haut":"#d4a017","accessoires":[]},"posture":"Fait ses lacets pour la troisième fois. Ses baskets brillent.","observer":{"texte":"Baskets blanches neuves, comme celles de {dylan}. Mais lui les a déjà salies au bout : une trace de ballon, une éraflure sur le côté.","indice":"lucas_baskets"},"questions":[{"id":"q1","q":"Elles viennent d'où, tes baskets ?","r":"Cadeau de ma grand-mère pour mes 17 ans ! Samedi. Elle a fait trois magasins, franchement c'est une dinguerie. Je les ai déjà niquées au basket, elle va me tuer.","indice":"lucas_anniv"},{"id":"q2","q":"Tu le connais, {dylan} ?","r":"Le mec là-bas ? Il m'a dit qu'il était en 1re B. Moi je suis en 1re B depuis septembre, et je l'ai jamais vu en cours.","indice":"lucas_dylan","apres":[]},{"id":"q3","q":"Tu viens demain ?","r":"Évidemment. J'amène les cadenas. Enfin, je dis rien, hein."},{"id":"q4","q":"Tu as qui en maths ?","requiert":"ines_garnier","r":"Haddad. Il est arrivé à la rentrée, il remplace Garnier. Il note dur mais il explique bien. Validé.","indice":"lucas_haddad"}],"fin":{"accuseATort":"{lucas} se fait traiter de « keuf » pendant des semaines. Il continue de venir au gymnase, mais il joue seul."},"infiltre":false}],"epilogue":{"parfait":"Ce soir, sur le groupe, Inès écrit : « Deux de moins. » Demain, le blocus tiendra. Mais quelqu'un, quelque part, est déjà en train de choisir de nouveaux déguisements.","moyen":"Le blocus aura lieu. Mais tu n'as pas tout vu, et ce que tu as raté, quelqu'un d'autre le paiera.","mauvais":"Le groupe se déchire. Plus personne ne sait qui croire. C'était peut-être ça, le vrai but."}},"2":{"jour":2,"titre":"Mardi. Ils savaient.","intro":["Ce matin, les poubelles ont bloqué la grille jusqu'à 10h. Puis la police est arrivée, en force. Au mégaphone, le commissaire a demandé à parler à « la Générale ». Ce surnom d'Inès, personne ne l'utilisait ailleurs que dans le groupe WhatsApp.","Un grand frère a été embarqué devant le lycée. Vendredi, un deuxième blocus est prévu, plus gros, avec deux autres lycées.","Inès a reçu un deuxième message : « Ils sont trois maintenant. Et l'un des vôtres leur parle. »"],"annonce":"Le message parlait de trois flics et d'une balance parmi les élèves.","actions":14,"heureDebut":11.5,"minutesParAction":24,"zones":[{"id":"entree","nom":"Entrée","decor":"La grille est encore tordue. Un camion de la mairie ramasse les poubelles du blocus."},{"id":"cantine","nom":"Cantine","decor":"Tout le monde ne parle que de ce matin. Les plateaux refroidissent."},{"id":"fumoir","nom":"Fumoir","decor":"Moins de monde que d'habitude. Ceux qui restent baissent la voix."},{"id":"gymnase","nom":"Gymnase","decor":"Cours de badminton annulé. Le prof est en réunion avec le proviseur."},{"id":"cdi","nom":"CDI","decor":"La documentaliste a scotché un article du journal local sur la porte."}],"indices":{"ines_balance":{"texte":"Inès : le commissaire a demandé « la Générale » au mégaphone. Ce surnom d'Inès n'existait que dans le groupe WhatsApp.","type":"info"},"ines_vendredi":{"texte":"Inès : pour vendredi, personne n'a encore l'heure ni le plan. Celui qui la réclame trop, c'est lui qu'il faut regarder.","type":"info"},"yanis_benali":{"texte":"{yanis} : M. Benali n'est prof principal que de classes de seconde.","type":"info"},"sarah_cpe":{"texte":"{sarah} : la CPE lui a dit qu'aucun surveillant n'a été recruté depuis la rentrée.","type":"info"},"jade_benali":{"texte":"{jade} dit être en terminale, avec M. Benali comme prof principal.","type":"suspect","sur":"jade"},"jade_stylo":{"texte":"Dans la trousse de {jade}, un stylo gravé « Ministère de l'Intérieur · Formation continue ».","type":"suspect","sur":"jade"},"jade_cpe":{"texte":"{jade} parle de « la conseillère principale d'éducation ». En toutes lettres. Personne ne dit ça.","type":"suspect","sur":"jade"},"jade_aveu":{"texte":"Coincée sur M. Benali, {jade} a répondu « on m'a mal renseignée ». Pas « je me suis trompée ». Mal renseignée.","type":"suspect","sur":"jade"},"samy_nouveau":{"texte":"{samy} est arrivé hier, en plein milieu de l'année. Comme {yanis} il y a deux semaines.","type":"suspect","sur":"samy"},"samy_photos":{"texte":"{samy} photographie la banderole du blocus, puis zoome sur les visages autour.","type":"suspect","sur":"samy"},"lucas_megane":{"texte":"{lucas} a vu {samy} descendre ce matin d'une voiture grise, une radio fixée au tableau de bord.","type":"suspect","sur":"samy"},"samy_aveu":{"texte":"Interrogé sur la voiture, {samy} a dit « c'est mon oncle », puis « mon père », dans la même phrase.","type":"suspect","sur":"samy"},"bastien_talkie":{"texte":"Le talkie de Bastien est noir, avec une antenne. Ceux de la vie scolaire sont jaunes et tout petits.","type":"suspect","sur":"bastien"},"bastien_liste":{"texte":"Bastien demande les noms de ceux qui étaient au blocus, « pour les féliciter ».","type":"suspect","sur":"bastien"},"bastien_badge":{"texte":"Bastien n'a pas de badge de la vie scolaire autour du cou.","type":"suspect","sur":"bastien"},"theo_telephone":{"texte":"{theo} a un téléphone neuf, dernier modèle. Hier il avait l'écran fissuré.","type":"suspect","sur":"theo"},"theo_groupe":{"texte":"{moussa} : {theo} lui a demandé la liste complète du groupe WhatsApp « pour l'admin ».","type":"suspect","sur":"theo"},"theo_frere":{"texte":"Théo est sûr que son frère « va sortir bientôt ». Quelqu'un le lui a promis.","type":"suspect","sur":"theo"},"theo_bastien":{"texte":"{chloe} a vu {theo} parler à Bastien derrière le gymnase ce matin, vers 8h.","type":"suspect","sur":"theo"},"chloe_absente":{"texte":"{chloe} n'était pas au blocus ce matin, elle qui est d'habitude au premier rang.","type":"suspect","sur":"chloe"},"chloe_alibi":{"texte":"{chloe} était convoquée au tribunal pour enfants à 9h, pour l'affaire de l'an dernier. Elle montre la convocation.","type":"innocent","sur":"chloe"},"sarah_article":{"texte":"Un article du journal local cite « une lycéenne » avec l'heure du blocus. On pense à {sarah}.","type":"suspect","sur":"sarah"},"sarah_alibi":{"texte":"{sarah} : l'article est sorti à 11h, après l'arrivée de la police. Elle montre l'heure de publication.","type":"innocent","sur":"sarah"},"yanis_cpe":{"texte":"{yanis} sort encore du bureau de la CPE.","type":"suspect","sur":"yanis"},"yanis_alibi":{"texte":"{yanis} : la CPE l'aide à remplir son dossier de bourse. Il montre le formulaire.","type":"innocent","sur":"yanis"},"kenzo2_retour":{"texte":"Sa vape fume maintenant, mais Kenzo recrache sans avaler, comme quelqu'un qui n'a jamais fumé.","type":"suspect","sur":"kenzo"},"kenzo2_t3":{"texte":"Kenzo veut savoir qui a eu l'idée des poubelles du blocus.","type":"suspect","sur":"kenzo"},"dylan2_retour":{"texte":"{dylan} est revenu avec des baskets salies exprès : la terre est fraîche, posée au doigt.","type":"suspect","sur":"dylan"},"dylan2_haddad":{"texte":"Dylan demande si c'est Inès qui décide de tout au comité.","type":"suspect","sur":"dylan"},"lea_liste":{"texte":"{lea} tient une liste de prénoms avec des heures, et note ceux des embarqués.","type":"suspect","sur":"lea"},"lea_noms":{"texte":"{lea} demande les noms de tous ceux qui ont été embarqués ce matin.","type":"suspect","sur":"lea"},"lea_nouvelle":{"texte":"{lea} est arrivée la semaine dernière, de Marseille. Personne ne la connaît.","type":"suspect","sur":"lea"},"lea_avocate":{"texte":"{lea} : sa mère est avocate et défend des victimes de violences policières. Sans les noms, pas d'avocat pour ceux en garde à vue. Elle montre sa carte.","type":"innocent","sur":"lea"},"moussa_karim":{"texte":"Moussa : Karim, le grand frère de Théo, a été embarqué ce matin. Il n'était même pas au blocus.","type":"info"},"bastien_nom":{"texte":"Bastien a demandé son nom de famille à Moussa. Les pions ne demandent jamais ça.","type":"suspect","sur":"bastien"},"theo_heure":{"texte":"Théo demande l'heure et le plan de vendredi, et si Inès les a donnés.","type":"suspect","sur":"theo"},"theo_excuse":{"texte":"Théo dit que Bastien lui a seulement « demandé l'heure ». Ses mains tremblent.","type":"suspect","sur":"theo"},"kenzo2_heure":{"texte":"Kenzo demande l'heure du blocus de vendredi, « pour son réveil ».","type":"suspect","sur":"kenzo"},"dylan2_heure":{"texte":"Dylan demande où et à quelle heure on se retrouve avant vendredi.","type":"suspect","sur":"dylan"},"sarah_jade":{"texte":"Sarah : Jade lui a demandé « les contacts des leaders ». Personne ne parle comme ça.","type":"suspect","sur":"jade"}},"pnj":[{"id":"ines","nom":"Inès","zone":"entree","infiltre":false,"allie":true,"posture":"Assise sur le muret, les yeux rouges. Elle n'a pas dormi.","sprite":{"peau":"#a8704a","cheveux":"long","couleurCheveux":"#1b1210","haut":"#5a2a6b","accessoires":["boucles"]},"observer":{"texte":"Elle tient son téléphone à deux mains et relit les messages du groupe, un par un, comme si les noms allaient s'avouer tout seuls."},"questions":[{"id":"q1","q":"Comment ils ont su ?","r":"Le commissaire a demandé « la Générale » au mégaphone. Ce surnom, c'était que dans le groupe WhatsApp. Donc quelqu'un de chez nous a parlé. Un vrai élève.","indice":"ines_balance"},{"id":"q2","q":"On fait quoi pour vendredi ?","r":"Personne n'a l'heure ni le plan, même pas moi. Exprès. Si quelqu'un insiste trop pour l'avoir, tu le notes.","indice":"ines_vendredi"},{"id":"q3","q":"Et si c'est quelqu'un qu'on aime bien ?","r":"Alors ce sera encore plus dur. Mais vendredi, il y aura trois lycées. Si on se trompe, c'est pas juste nous qui tombons.","gratuit":true}]},{"id":"bastien","nom":"Bastien","zone":"entree","infiltre":true,"grade":"Brigadier-chef Faure, 31 ans, renseignement territorial","posture":"« Nouveau surveillant ». Sourire large, talkie à la ceinture.","sprite":{"peau":"#e8c0a0","cheveux":"rase","couleurCheveux":"#6b4a2a","haut":"#444a5a","accessoires":["lunettes"]},"observer":{"texte":"Il se présente comme le nouveau pion. Son talkie est noir, épais, avec une antenne. Ceux de la vie scolaire sont jaunes et tiennent dans la main.","indice":"bastien_talkie"},"questions":[{"id":"q1","q":"T'es nouveau, toi ?","r":"Depuis ce matin ! Surveillant. Dis-moi, t'étais au blocus ce matin ? Franchement, c'était trop de la balle. Tu peux me dire qui y était ? J'aimerais féliciter tout le monde, personnellement.","indice":"bastien_liste"},{"id":"q2","q":"Il est où, ton badge ?","r":"Mon badge ? Oublié à la maison. Ça arrive à tout le monde, non ?","indice":"bastien_badge"},{"id":"q3","q":"La CPE dit qu'elle n'a recruté personne.","requiert":"sarah_cpe","r":"Son sourire tient une seconde de trop. « Je suis rattaché au rectorat. C'est compliqué. » Il s'éloigne en parlant dans son talkie."}],"fin":{"demasque":"Le soir même, Bastien n'est plus là. La CPE confirme : personne ne l'avait embauché. Sur le parking, une voiture banalisée démarre.","sansPreuve":"« Moi, un flic ? Tu regardes trop de séries. » Sans preuve, le groupe rit. Bastien te fait un petit signe de la main.","rate":"Demain, Bastien est encore à l'entrée, sous un autre badge. Il coche les noms de ceux qui arrivent, sur une feuille qui n'est pas celle du lycée."}},{"id":"lea","nom":"{lea}","zone":"entree","infiltre":false,"posture":"Cahier à spirale ouvert, elle note des prénoms et des heures.","sprite":{"peau":"#c48a62","cheveux":"long","couleurCheveux":"#3b2416","haut":"#7a2f3f","accessoires":[]},"observer":{"texte":"Une liste de prénoms, avec une heure à côté de chacun. Elle a souligné ceux qui ont été embarqués ce matin. Tu ne l'avais jamais vue avant la semaine dernière.","indice":"lea_liste"},"questions":[{"id":"q1","q":"Tu notes quoi ?","r":"Les noms des embarqués, l'heure, le commissariat. Il m'en manque, et dégun veut me les donner. C'est tarpin relou. Tu sais qui d'autre a été pris ?","indice":"lea_noms"},{"id":"q2","q":"T'es arrivée quand, toi ?","r":"La semaine dernière. Je viens de Marseille, ma mère a changé de cabinet. Vous êtes fadas, ici, avec vos blocus à l'aube.","indice":"lea_nouvelle"},{"id":"q3","q":"Pourquoi tu as besoin de leurs noms ?","apres":["q1"],"r":"Ma mère est avocate. Elle défend des victimes de violences policières avec un collectif : sans nom, pas d'avocat pour ceux en garde à vue. Tiens, sa carte. Appelle si tu me crois pas.","indice":"lea_avocate"}],"fin":{"accuseATort":"{lea} referme son cahier et ne l'ouvre plus. Ce soir, deux élèves passent la nuit en garde à vue sans avocat : leurs noms n'étaient sur aucune liste."}},{"id":"samy","nom":"{samy}","zone":"entree","sprite":{"peau":"#b07850","cheveux":"court","couleurCheveux":"#1a120c","haut":"#3a5a3a","accessoires":[]},"posture":"Nouveau depuis hier. Prend des photos « pour le souvenir ».","observer":{"texte":"Il photographie la banderole du blocus, encore accrochée à la grille. Puis il tourne le téléphone vers les élèves autour, et zoome sur les visages.","indice":"samy_photos"},"questions":[{"id":"q1","q":"Tu viens d'où ?","r":"J'arrive d'un autre lycée. Hier. Changement d'adresse, tu vois. C'est la vie.","indice":"samy_nouveau"},{"id":"q2","q":"Pourquoi tu prends tout en photo ?","r":"Pour le souvenir, frère. C'est historique, ce qui se passe ici. Tu veux être dessus ?"},{"id":"q3","q":"C'était qui, dans la voiture grise ?","requiert":"lucas_megane","r":"« C'est mon oncle. Mon père. Enfin, mon oncle qui est comme un père. » Il range son téléphone.","indice":"samy_aveu"}],"fin":{"demasque":"{samy} efface ses photos devant tout le monde, trop tard : elles sont déjà parties. Il ne revient pas mercredi. Son dossier d'inscription n'a jamais existé.","sansPreuve":"« Moi ? Parce que je suis nouveau ? Comme {yanis} ? » Le groupe se tourne vers toi. Sans preuve, c'est toi qui as l'air de chercher un coupable.","rate":"Les photos de {samy} servent à identifier quatorze élèves. Les parents reçoivent des courriers jeudi."},"grade":"Gardien de la paix Roux, 25 ans","infiltre":true},{"id":"moussa","nom":"{moussa}","zone":"cantine","infiltre":false,"posture":"Ne négocie même pas son dessert. Mauvais signe.","sprite":{"peau":"#4a2e20","cheveux":"court","couleurCheveux":"#0e0a08","haut":"#b33a2a","accessoires":[]},"observer":{"texte":"Il regarde {theo}, deux tables plus loin, avec une tête que tu ne lui connais pas."},"questions":[{"id":"q1","q":"Pourquoi tu regardes {theo} comme ça ?","r":"Hier soir il m'a demandé la liste complète du groupe WhatsApp. « Pour l'admin », il a dit. {theo}, il est même pas admin.","indice":"theo_groupe","apres":["obs"]},{"id":"q2","q":"Qui a été embarqué ce matin ?","r":"Karim, le grand frère de {theo}. Il passait juste devant, il était même pas au blocus. Garde à vue. Miskin.","indice":"moussa_karim"},{"id":"q3","q":"Tu as vu le nouveau pion ?","r":"Bastien ? Il m'a demandé mon nom de famille. Les pions, ils s'en foutent de ton nom de famille.","indice":"bastien_nom"}],"fin":{"accuseATort":"{moussa} quitte le groupe WhatsApp. « Après tout ce que j'ai fait. » Il reste au lycée, mais il ne te parle plus."}},{"id":"theo","nom":"{theo}","zone":"cantine","infiltre":true,"grade":"Pas un flic. {theo}, 16 ans, vrai élève. La police lui a promis de relâcher son frère s'il donnait des noms.","posture":"Mange seul, téléphone neuf posé à côté du plateau.","sprite":{"peau":"#f0c4a0","cheveux":"boucle","couleurCheveux":"#7a4a20","haut":"#2a6b8a","accessoires":[]},"observer":{"texte":"Un téléphone neuf, dernier modèle, encore avec le film sur l'écran. Hier, le sien était fissuré de partout. Il le retourne quand quelqu'un passe.","indice":"theo_telephone"},"questions":[{"id":"q1","q":"Ça va, pour ton frère ?","r":"Il... ça va aller. Il va sortir. Bientôt. On m'a dit qu'il allait sortir.","indice":"theo_frere","apres":["moussa:q2"]},{"id":"q2","q":"Tu viens vendredi ?","r":"Ouais, bien sûr. C'est à quelle heure, d'ailleurs ? Et c'est quoi le plan ? Inès t'a dit ?","indice":"theo_heure"},{"id":"q3","q":"Tu parlais à Bastien derrière le gymnase ?","requiert":"theo_bastien","r":"Il pose sa fourchette. Ses mains tremblent. « Il m'a demandé l'heure. C'est tout. » Il ne te regarde plus.","indice":"theo_excuse"}],"fin":{"demasque":"Théo pleure. Depuis la semaine dernière, on le tient avec le sursis de son frère. C'est lui qui a donné l'heure du blocus de ce matin, et rapporté ce qui se disait dans le groupe. Karim a été embarqué quand même, « pour que Théo continue ». Personne ne sait s'il faut le haïr.","sansPreuve":"{theo} nie, les larmes aux yeux. Sans preuve, le groupe le console. Et il t'en veut.","rate":"Vendredi, la liste complète du groupe est sur le bureau d'un commissaire. Avec les numéros de téléphone."},"balance":true},{"id":"chloe","nom":"{chloe}","zone":"fumoir","infiltre":false,"posture":"Dos au mur, bras croisés. Tout le monde la regarde de travers.","sprite":{"peau":"#f2d0b5","cheveux":"capuche","couleurCheveux":"#151515","haut":"#111111","accessoires":["boucles"]},"observer":{"texte":"Elle n'était pas au blocus ce matin. Elle, toujours au premier rang. Des gens chuchotent en la regardant.","indice":"chloe_absente"},"questions":[{"id":"q1","q":"T'étais où ce matin ?","r":"Au tribunal pour enfants, à 9h. Pour l'affaire de l'an dernier. Tiens, la convocation. Tu crois que j'ai choisi la date ?","indice":"chloe_alibi","apres":["obs"]},{"id":"q2","q":"T'as vu quelque chose de bizarre ?","r":"Ce matin, vers 8h, avant que je parte au tribunal : {theo}, derrière le gymnase, avec le nouveau pion. Ils parlaient bas. {theo} avait l'air de vouloir disparaître.","indice":"theo_bastien"},{"id":"q3","q":"Tu nous en veux ?","r":"Askip je suis une balance, maintenant ? Je vous en veux de me regarder comme ça. C'est exactement ce qu'ils veulent."}],"fin":{"accuseATort":"{chloe} est accusée deux années de suite, par la police puis par les siens. Elle revient le lendemain, mais elle ne s'assoit plus avec vous."},"reserve":true},{"id":"kenzo","nom":"{kenzo}","zone":"fumoir","infiltre":true,"condition":{"rateLaVeille":"kenzo"},"grade":"Brigadier Laurent, 34 ans","posture":"Il est revenu. Même casquette à l'envers, même sweat gris. La vape fume, cette fois.","sprite":{"peau":"#e0b190","cheveux":"casquette","couleurCheveux":"#5b3a22","haut":"#7a2a2a","accessoires":["vape"]},"observer":{"texte":"Même casquette à l'envers, même sweat gris. La vape fume, cette fois. Mais il recrache la fumée sans l'avoir inhalée, comme quelqu'un qui n'a jamais fumé.","indice":"kenzo2_retour"},"questions":[{"id":"q1","q":"T'as vu quelque chose, ce matin ?","r":"Grave, c'était dingue ! Dis, c'est qui qui a eu l'idée des poubelles ? Faut que je lui serre la main.","indice":"kenzo2_t3"},{"id":"q2","q":"Tu viens vendredi ?","r":"Grave. C'est à quelle heure, déjà ? Je demande pour mon réveil.","indice":"kenzo2_heure"}],"fin":{"demasque":"Deux jours de suite, la même casquette. Cette fois, le fumoir entier le raccompagne jusqu'à la grille.","sansPreuve":"Il rit, mais moins fort.","rate":"{kenzo} est toujours là. Il apprend vite, et il prend des notes."}},{"id":"lucas","nom":"{lucas}","zone":"gymnase","infiltre":false,"posture":"Joue au basket seul. Il a l'air d'avoir vu un truc.","sprite":{"peau":"#e8b896","cheveux":"court","couleurCheveux":"#c49a4a","haut":"#d4a017","accessoires":[]},"observer":{"texte":"Il tire, rate, ramasse le ballon, et regarde vers l'entrée à chaque fois."},"questions":[{"id":"q1","q":"T'as vu quelque chose ce matin ?","r":"Le nouveau, {samy}. Il est descendu d'une voiture grise devant le lycée. Y avait une radio, genre une vraie, fixée au tableau de bord. Mon oncle est taxi, c'est pas une radio de taxi.","indice":"lucas_megane"},{"id":"q2","q":"Tu viens vendredi ?","r":"Évidemment. J'amène les cadenas, ceux que la police n'a pas trouvés ce matin."}],"fin":{"accuseATort":"{lucas} rend les cadenas à Inès sans un mot. Vendredi, la grille tient moins longtemps."},"reserve":true},{"id":"dylan","nom":"{dylan}","zone":"gymnase","infiltre":true,"condition":{"rateLaVeille":"dylan"},"grade":"Gardien de la paix Morel, 29 ans","posture":"Revenu, mêmes baskets blanches, très décontracté. Trop décontracté.","sprite":{"peau":"#d9a27a","cheveux":"rase","couleurCheveux":"#2a1a12","haut":"#1f2b5c","accessoires":["oreillette"]},"observer":{"texte":"Mêmes baskets blanches, mais maculées de terre fraîche, posée en petites traces régulières, comme au doigt. Il garde son écouteur droit.","indice":"dylan2_retour"},"questions":[{"id":"q1","q":"Tu faisais quoi pendant le blocus, ce matin ?","r":"J'étais là, tranquille. Mais c'est Inès qui décide de tout, non ? C'est elle qu'il faut convaincre pour vendredi ?","indice":"dylan2_haddad"},{"id":"q2","q":"Tu viens vendredi ?","r":"Ouais. Vous vous retrouvez où, avant ? Et à quelle heure ?","indice":"dylan2_heure"}],"fin":{"demasque":"{dylan} ne prend même pas la peine de nier. Il sort par le portail des profs, comme s'il en avait les clés.","sansPreuve":"« Moi, un flic ? » Il sourit. Il sait que personne ne te croit.","rate":"La liste de {dylan} s'est allongée. Ton nom est toujours dessus."}},{"id":"sarah","nom":"{sarah}","zone":"cdi","infiltre":false,"posture":"Écrit vite. Quelqu'un a gribouillé « BALANCE » sur son carnet.","sprite":{"peau":"#f0c8a8","cheveux":"chignon","couleurCheveux":"#a3502a","haut":"#2d5a3a","accessoires":["lunettes"]},"observer":{"texte":"Sur la porte du CDI, un article du journal local cite « une lycéenne » avec l'heure exacte du blocus. Tout le monde pense que c'est elle.","indice":"sarah_article"},"questions":[{"id":"q1","q":"C'est toi, dans l'article ?","r":"Oui, c'est ma citation. Regarde l'heure de publication : 11h04. La police était là à 10h. Je n'ai rien donné avant, j'ai raconté après.","indice":"sarah_alibi","apres":["obs"]},{"id":"q2","q":"Tu sais quelque chose sur le nouveau pion ?","r":"J'ai demandé à la CPE pour mon article. Elle n'a recruté aucun surveillant depuis la rentrée. Aucun.","indice":"sarah_cpe"},{"id":"q3","q":"Et la fille au CDI, {jade} ?","r":"Elle m'a demandé si j'avais « les contacts des leaders ». Les leaders. Personne ne parle comme ça.","indice":"sarah_jade"}],"fin":{"accuseATort":"{sarah} continue d'écrire, mais plus une ligne sur le blocus. Le seul récit qui circule, c'est celui de la préfecture."}},{"id":"yanis","nom":"{yanis}","zone":"cdi","sprite":{"peau":"#6b4530","cheveux":"boucle","couleurCheveux":"#120c0a","haut":"#24486b","accessoires":["lunettes"]},"posture":"Revient du bureau de la CPE, une pochette sous le bras.","observer":{"texte":"Il sort encore du bureau de la CPE. {chloe} l'a vu aussi, et elle le dit à qui veut l'entendre.","indice":"yanis_cpe"},"questions":[{"id":"q1","q":"Tu fais quoi chez la CPE ?","r":"Mon dossier de bourse. Ma mère comprend pas les formulaires, alors la CPE m'aide. Tiens, regarde.","indice":"yanis_alibi"},{"id":"q2","q":"M. Benali, il a quelles classes ?","r":"Que des secondes. Il est prof principal de ma classe, la 2nde 3. Pourquoi ?","indice":"yanis_benali","apres":["jade:q1"]},{"id":"q3","q":"Tu viens vendredi ?","r":"Ouais. Après ce qu'ils ont fait à Karim, ouais."}],"fin":{"accuseATort":"Deux fois en deux jours, quelqu'un a écrit sur le casier de {yanis}. Sa mère demande un changement d'établissement."},"infiltre":false},{"id":"jade","nom":"{jade}","zone":"cdi","sprite":{"peau":"#c98e6a","cheveux":"long","couleurCheveux":"#3a2418","haut":"#c43c6b","accessoires":["boucles"]},"posture":"Révise « le bac ». Le manuel est à l'envers depuis dix minutes.","observer":{"texte":"Elle a bien travaillé : bonnes baskets, bonne trousse, bonne coque de téléphone. Mais dans la trousse, un stylo gravé « Ministère de l'Intérieur · Formation continue ».","indice":"jade_stylo"},"questions":[{"id":"q1","q":"T'es dans quelle classe ?","r":"Terminale. Avec M. Benali en prof principal. Il est trop bien, franchement.","indice":"jade_benali"},{"id":"q2","q":"Tu traînes jamais au fumoir ?","r":"Non, la conseillère principale d'éducation passe souvent par là, je préfère éviter.","indice":"jade_cpe"},{"id":"q3","q":"Benali n'a que des secondes.","requiert":"yanis_benali","r":"« On m'a mal renseignée. » Elle se mord la lèvre. Elle sait ce qu'elle vient de dire.","indice":"jade_aveu","apres":["q1"]}],"fin":{"demasque":"{jade} referme son manuel, à l'endroit cette fois. « Bien joué. » Elle sort calmement. Elle a l'air presque impressionnée.","sansPreuve":"{jade} te regarde avec pitié. « Tu vas bien ? Tu veux en parler à quelqu'un ? » Sans preuve, c'est toi qui passes pour le parano.","rate":"{jade} a maintenant les numéros de trois « leaders ». Mercredi, elle déjeune avec eux."},"grade":"Lieutenante Mercier, 27 ans","infiltre":true}],"epilogue":{"parfait":"Le groupe WhatsApp est recréé, à dix, sur une autre appli. Pour la première fois depuis lundi, Inès dort. Vendredi est encore loin.","moyen":"Vendredi se prépare quand même. Avec des trous dans le groupe, et des gens qui ne se parlent plus.","mauvais":"Plus personne ne poste dans le groupe. Chacun soupçonne tout le monde. Ils n'ont presque plus besoin d'infiltrés."}},"3":{"jour":3,"titre":"Mercredi. Ils ont appris.","intro":["Depuis hier, un portique filtre l'entrée. Les infiltrés aussi ont changé : plus de photos, plus de talkie qui dépasse. Ils ont corrigé leurs erreurs de lundi et de mardi.","Cette nuit, aucun nouveau message. C'est ce qui inquiète Inès : « Quand ils se taisent, c'est qu'ils ont changé de méthode. »","Cette fois, ce n'est plus la tenue ni l'argot qui les trahira. Ce qui leur manque, c'est la mémoire du lycée : ce que seuls savent ceux qui y vivent.","À 7h, le numéro anonyme se réveille : « Deux nouveaux, mieux préparés. Et un autre des vôtres a été retourné. »"],"actions":11,"heureDebut":8,"minutesParAction":44,"zones":[{"id":"entree","nom":"Entrée","decor":"Le portique est tout neuf. Quelqu'un a décidé de « sécuriser » le lycée."},{"id":"cantine","nom":"Cantine","decor":"Même odeur de frites. Mais on parle moins fort qu'hier."},{"id":"fumoir","nom":"Fumoir","decor":"Le seul endroit où personne n'a installé de caméra. Pour l'instant."},{"id":"gymnase","nom":"Gymnase","decor":"Match de hand dans le fond. Les cris couvrent les conversations."},{"id":"cdi","nom":"CDI","decor":"La documentaliste vous regarde par-dessus ses lunettes. Elle sait."}],"indices":{"ines3_memoire":{"texte":"Faits que seuls les élèves connaissent : les lasagnes périmées du 14 mars, Mme Okafor (SVT, prof principale des T2), le proviseur surnommé « Monsieur Sourire ».","type":"info"},"ines3_details":{"texte":"Inès : ils copient désormais les tenues et l'argot. Ce qu'ils ne savent pas, c'est l'histoire du lycée.","type":"info"},"duval_asso":{"texte":"Mme Duval se dit « intervenante de l'association Prévention Jeunesse ».","type":"info"},"moussa3_duval":{"texte":"{moussa} connaît tous les adultes du lycée. Il n'a jamais vu Mme Duval.","type":"info"},"sarah3_asso":{"texte":"{sarah} : l'association « Prévention Jeunesse » n'existe dans aucun registre de l'académie.","type":"suspect","sur":"duval"},"duval_badge":{"texte":"Le badge de Mme Duval est plastifié maison, sans logo. Son cordon est celui de la police nationale.","type":"suspect","sur":"duval"},"duval_meneurs":{"texte":"Mme Duval demande qui anime le groupe du blocus, « pour proposer un dialogue ».","type":"suspect","sur":"duval"},"duval_aveu":{"texte":"Mme Duval a quitté la discussion à la mention du rectorat, et rejoint une voiture grise sans marquage.","type":"suspect","sur":"duval"},"nolan_prenoms":{"texte":"{nolan} prononce les prénoms des surveillants avec soin, comme appris la veille.","type":"suspect","sur":"nolan"},"nolan_ancien":{"texte":"{nolan} dit être « un ancien », au lycée depuis la seconde.","type":"info"},"nolan_sourire":{"texte":"{nolan} ne sait pas pourquoi le proviseur est surnommé « Monsieur Sourire » (« parce qu'il sourit tout le temps »).","type":"suspect","sur":"nolan"},"nolan_lasagnes":{"texte":"{nolan} se dit enthousiaste pour « les lasagnes » de l'an dernier, sans savoir qu'elles étaient périmées.","type":"suspect","sur":"nolan"},"nolan_sarah":{"texte":"{nolan} connaissait le nom de {sarah} avant qu'elle le dise. Ils ne s'étaient jamais parlé.","type":"suspect","sur":"nolan"},"rayan_veste":{"texte":"Rayan porte une veste en cuir neuve, sans le moindre pli.","type":"suspect","sur":"rayan"},"rayan_alibi":{"texte":"{rayan} : la veste est un cadeau de sa grande sœur pour son premier CDI.","type":"innocent","sur":"rayan"},"b3_talkie":{"texte":"L'antenne du talkie noir dépasse de la poche de Bastien. Toujours pas de badge de la vie scolaire.","type":"suspect","sur":"bastien"},"b3_nie":{"texte":"Bastien demande si le comité compte contourner le portique vendredi.","type":"suspect","sur":"bastien"},"b3_porte":{"texte":"Bastien demande qui sera à l'entrée vendredi matin, « pour la sécurité des gamins ».","type":"suspect","sur":"bastien"},"s3_cahier":{"texte":"{samy} dessine le plan de la grille avec des horaires, dans un cahier.","type":"suspect","sur":"samy"},"s3_okafor":{"texte":"{samy} dit avoir « Mme Okafor en arts plastiques ». Elle enseigne la SVT.","type":"suspect","sur":"samy"},"s3_heure":{"texte":"{samy} demande l'heure du blocus, « pour mon réveil ».","type":"suspect","sur":"samy"},"j3_tel":{"texte":"Le téléphone de {jade} est en mode avion en permanence, sans une notification. Un téléphone de service.","type":"suspect","sur":"jade"},"j3_roman":{"texte":"{jade} lit « L'Étranger » depuis une heure, marque-page à la page 3.","type":"suspect","sur":"jade"},"j3_okafor":{"texte":"{jade} prend Mme Okafor pour une prof de maths. Elle est en SVT.","type":"suspect","sur":"jade"},"t3_notif":{"texte":"Sur le téléphone neuf de {theo} s'affiche : « Alors, la suite ? »","type":"suspect","sur":"theo"},"t3_dimanche":{"texte":"{theo} : on lui a dit que Karim sortirait dimanche s'il continue.","type":"suspect","sur":"theo"},"k3_toux":{"texte":"La vape de {kenzo} fume, mais il tousse à chaque bouffée.","type":"suspect","sur":"kenzo"},"k3_echange":{"texte":"Kenzo veut savoir si le comité a un plan pour contourner le portique.","type":"suspect","sur":"kenzo"},"k3_sourire":{"texte":"{kenzo} pense que « Monsieur Sourire » est le prof de sport.","type":"suspect","sur":"kenzo"},"d3_barbe":{"texte":"{dylan} porte toujours son écouteur droit, mais le fil ne va nulle part : c'est une oreillette.","type":"suspect","sur":"dylan"},"d3_stagiaire":{"texte":"Dylan demande par où le comité compte passer vendredi, avec le portique.","type":"suspect","sur":"dylan"},"d3_okafor":{"texte":"{dylan} prend Mme Okafor pour une prof de sport. Elle est en SVT.","type":"suspect","sur":"dylan"},"rayan_okafor_ok":{"texte":"Rayan sait que Mme Okafor enseigne la SVT et qu'elle est prof principale des T2.","type":"innocent","sur":"rayan"},"malik3_filme":{"texte":"{malik} filme la grille et l'entrée avec son téléphone tenu bas, contre sa cuisse.","type":"suspect","sur":"malik"},"malik3_arrange":{"texte":"{malik} : le scooter de son oncle a été contrôlé lundi, sans papiers. Puis « ça s'est arrangé, tout seul ».","type":"suspect","sur":"malik"},"malik3_entree":{"texte":"{malik} veut savoir combien vous serez à l'entrée vendredi, « pour savoir où se mettre ».","type":"suspect","sur":"malik"},"malik3_scooter":{"texte":"{moussa} : le scooter de l'oncle de {malik} a été saisi lundi. Mardi, il roulait à nouveau.","type":"suspect","sur":"malik"},"malik3_aveu":{"texte":"Interrogé sur le scooter, Malik esquive. Son téléphone vibre et il le serre, sans regarder l'écran.","type":"suspect","sur":"malik"},"rayan_voiture":{"texte":"{rayan} arrivera vendredi en voiture, déposé par quelqu'un « qui veut voir ça ».","type":"suspect","sur":"rayan"},"moussa_nolan":{"texte":"Moussa : Nolan dit être là depuis la seconde, mais Moussa ne l'a jamais vu, ni en cours ni à la cantine.","type":"suspect","sur":"nolan"}},"pnj":[{"id":"ines","nom":"Inès","zone":"entree","infiltre":false,"allie":true,"posture":"Elle a retiré son bonnet. Elle a l'air de quelqu'un qui n'a pas dormi depuis lundi.","sprite":{"peau":"#a8704a","cheveux":"long","couleurCheveux":"#1b1210","haut":"#5a2a6b","accessoires":["boucles"]},"observer":{"texte":"Elle surveille le portique neuf comme une bête qu'on ne connaît pas encore."},"questions":[{"id":"q1","q":"Qu'est-ce qui a changé ?","r":"Les tenues, l'argot, les baskets : ils ont tout corrigé. Maintenant ils se trompent sur ce que seuls les gens d'ici savent : les profs, les surnoms, ce qui s'est passé l'an dernier.","indice":"ines3_details"},{"id":"q2","q":"Un exemple de ce qu'on est les seuls à savoir ?","r":"Les lasagnes, le 14 mars : quarante et un malades. Mme Okafor, notre prof de SVT, qui est prof principale des T2. Et le proviseur, qu'on appelle « Monsieur Sourire » parce qu'il ne sourit jamais.","indice":"ines3_memoire"},{"id":"q3","q":"Tu tiens le coup ?","r":"Non. Mais si je lâche, qui prévient les autres ?","gratuit":true}]},{"id":"duval","nom":"Mme Duval","zone":"entree","infiltre":true,"grade":"Capitaine Duval, 41 ans, renseignement territorial","posture":"Blazer beige, brochures sur les « bons réflexes ». Sourit à tous les lycéens qui passent.","sprite":{"peau":"#f0c8a8","cheveux":"long","couleurCheveux":"#7a5a3a","haut":"#b8a27a","accessoires":["lunettes"]},"observer":{"texte":"Le badge est plastifié maison, sans logo. Le cordon est bleu avec un liseré blanc, celui de la police nationale.","indice":"duval_badge"},"questions":[{"id":"q1","q":"Vous êtes de quelle association ?","r":"Prévention Jeunesse. Nous intervenons auprès des lycéens pour les protéger des mauvaises rencontres.","indice":"duval_asso"},{"id":"q2","q":"Vous cherchez quoi ici ?","r":"Je discute, j'écoute leurs besoins. Qui anime le groupe de discussion du blocus, par exemple ? Je pourrais proposer un dialogue avec la direction.","indice":"duval_meneurs"},{"id":"q3","q":"Vous avez un contact au rectorat ?","r":"Elle regarde l'heure, dit « je dois y aller » et rejoint une voiture grise sans marquage, garée devant l'entrée.","indice":"duval_aveu","requiert":"sarah3_asso","apres":["q1"]}],"fin":{"demasque":"Mme Duval repart en laissant ses brochures. À la dernière page, un numéro de téléphone qui n'est pas celui d'une association.","sansPreuve":"« Moi, une flic ? Vous exagérez. » Sans preuve, la moitié du groupe plaide pour la laisser parler.","rate":"Mme Duval a un rendez-vous avec le proviseur à 14h. Elle en sort avec une liste de noms « à surveiller »."}},{"id":"malik","nom":"{malik}","zone":"entree","infiltre":true,"grade":"{malik}, 17 ans, vrai élève sous pression","posture":"Le nouveau de lundi. Il fait les cent pas devant la grille, téléphone à la main.","sprite":{"peau":"#8a5a3c","cheveux":"court","couleurCheveux":"#100b08","haut":"#3d6b4f","accessoires":[]},"observer":{"texte":"Il fait semblant de lire ses messages. Mais son téléphone est tenu bas, contre sa cuisse, l'objectif tourné vers la grille et ceux qui entrent.","indice":"malik3_filme"},"questions":[{"id":"q1","q":"Ça va, le boulot avec ton oncle ?","r":"Ils ont contrôlé son scooter lundi. Pas de papiers, pas d'assurance. Et puis... ça s'est arrangé. Tout seul.","indice":"malik3_arrange"},{"id":"q2","q":"Tu viens vendredi ?","r":"Ouais, ouais. Vous serez combien à l'entrée, vous ? Juste pour savoir où me mettre.","indice":"malik3_entree"},{"id":"q3","q":"Le scooter, ça s'arrange pas tout seul.","requiert":"malik3_scooter","apres":["q1"],"r":"Il baisse les yeux. « Je sais pas. Ça s'est arrangé, c'est tout. » Son téléphone vibre. Il ne regarde pas l'écran, mais il le serre plus fort.","indice":"malik3_aveu"}],"fin":{"demasque":"{malik} pleure sans bruit. Il donne le prénom du policier qui l'appelle tous les soirs. Inès le fait sortir du groupe, mais personne ne le livre. « Lundi, on t'a cru. On te croit encore un peu. »","sansPreuve":"« Moi ? J'ai rien fait ! » {malik} s'en va en courant. Sans preuve, on le laisse partir.","rate":"Ce soir, {malik} envoie une vidéo de la grille, de l'entrée et de ceux qui y passent. Il ne dort pas de la nuit."},"balance":true},{"id":"bastien","nom":"Bastien","zone":"entree","infiltre":true,"condition":{"rateLaVeille":"bastien"},"grade":"Brigadier-chef Faure, 31 ans","posture":"Même sourire large. Il surveille l'entrée, comme hier.","sprite":{"peau":"#e8c0a0","cheveux":"rase","couleurCheveux":"#6b4a2a","haut":"#2a6b9a","accessoires":["lunettes"]},"observer":{"texte":"Le talkie est rangé dans la poche de sa veste, mais l'antenne noire dépasse encore. Toujours pas de badge de la vie scolaire autour du cou.","indice":"b3_talkie"},"questions":[{"id":"q1","q":"Tu surveilles le portique, aujourd'hui ?","r":"Le portique, ouais. Ça vous gêne ? Vous comptez le contourner, vendredi ?","indice":"b3_nie"},{"id":"q2","q":"Tu fais quoi, à l'entrée ?","r":"Je surveille, c'est mon boulot. Dis-moi, qui sera à l'entrée vendredi matin ? Pour la sécurité des gamins.","indice":"b3_porte"}],"fin":{"demasque":"Bastien sourit en partant. « À vendredi », dit-il en montant dans la voiture banalisée. Personne ne rit.","sansPreuve":"« Moi, un flic ? » Le groupe rit. Sans preuve, c'est toi qu'on regarde de travers.","rate":"Mercredi soir, Bastien connaît l'heure d'ouverture de la grille de vendredi. Quelqu'un le lui a dit."}},{"id":"moussa","nom":"{moussa}","zone":"cantine","infiltre":false,"posture":"Il scrute la cantine comme un surveillant d'examen.","sprite":{"peau":"#4a2e20","cheveux":"court","couleurCheveux":"#0e0a08","haut":"#b33a2a","accessoires":[]},"observer":{"texte":"Il a un nom, un surnom et une anecdote pour chaque adulte du lycée. Aujourd'hui, il en cherche un qui lui échappe."},"questions":[{"id":"q1","q":"Tu connais tous les adultes ici ?","r":"Les profs, les pions, la CPE, le proviseur, l'infirmière, la dame de la cantine. Et pas Mme Duval, la dame au blazer. Elle dit qu'elle est de « Prévention Jeunesse ».","indice":"moussa3_duval","requiert":"duval_asso"},{"id":"q2","q":"{rayan}, sa veste neuve ?","r":"{rayan} ? Il est dans ma classe depuis la seconde. La veste, c'est le cadeau de sa grande sœur qui a eu son premier CDI. Il en parle depuis lundi, il nous saoule grave.","indice":"rayan_alibi","requiert":"rayan_veste"},{"id":"q3","q":"Et {nolan} ?","r":"Nolan ? Il dit qu'il est là depuis la seconde. Moi, je l'ai jamais vu en cours. Ni au conseil de classe, ni à la cantine. Teste-le sur ce qu'on sait tous.","indice":"moussa_nolan"},{"id":"q4","q":"Et {malik}, le nouveau de lundi ?","r":"Son oncle s'est fait saisir le scooter lundi. Il pleurait, il disait qu'ils allaient tout perdre. Et mardi, le scooter roulait. Bizarre, non ?","indice":"malik3_scooter"}],"fin":{"accuseATort":"{moussa} t'écoute dire son nom devant tout le monde. Il ne dit rien. Le lendemain, il a rendu son badge de délégué. Le lycée a perdu sa mémoire."}},{"id":"samy","nom":"{samy}","zone":"cantine","infiltre":true,"condition":{"rateLaVeille":"samy"},"grade":"Gardien de la paix Roux, 25 ans","posture":"Il dessine dans un cahier, sans téléphone. Un plan de la grille, des flèches.","sprite":{"peau":"#b07850","cheveux":"court","couleurCheveux":"#1a120c","haut":"#6b3a1a","accessoires":[]},"observer":{"texte":"Il a abandonné le téléphone. À la place, un cahier : le plan de la grille, des flèches, des minutes.","indice":"s3_cahier"},"questions":[{"id":"q1","q":"Ton cahier, c'est pour quel cours ?","r":"Arts plastiques, avec Mme Okafor. Elle adore les perspectives.","indice":"s3_okafor"},{"id":"q2","q":"Tu seras où, vendredi ?","r":"Ici, comme tout le monde. Tu me donnes l'heure, pour mon réveil ?","indice":"s3_heure"}],"fin":{"demasque":"{samy} referme son cahier et le glisse sous son pull. À la page du plan, une annotation : « entrée secondaire non couverte ».","sansPreuve":"« Moi, un flic ? » Samy te regarde, vexé. Sans preuve, c'est toi qui deviens le problème.","rate":"Le plan de la grille de {samy} est sur un bureau, ce soir. Avec les heures, au quart d'heure près."}},{"id":"theo","nom":"{theo}","zone":"cantine","infiltre":true,"condition":{"rateLaVeille":"theo"},"grade":"{theo}, 16 ans, vrai élève sous pression","posture":"Seul à une table. Il fixe son téléphone sans le toucher.","sprite":{"peau":"#f0c4a0","cheveux":"boucle","couleurCheveux":"#7a4a20","haut":"#2a6b8a","accessoires":[]},"observer":{"texte":"Il a les yeux cernés. Sur son téléphone neuf, une notification s'allume : « Alors, la suite ? ».","indice":"t3_notif"},"questions":[{"id":"q1","q":"Ça va aller ?","r":"J'ai pas le choix. Ils me disent que Karim sort dimanche si je continue.","indice":"t3_dimanche"}],"fin":{"demasque":"Quand quelqu'un lui tend la main, {theo} craque et dit tout. Le groupe décide, ce soir, de le protéger. C'est la première fois cette semaine que personne n'est seul.","sansPreuve":"{theo} nie en pleurant. Sans preuve, on le console.","rate":"{theo} envoie la liste du comité. Dimanche, Karim ne sort pas."}},{"id":"nolan","nom":"{nolan}","zone":"fumoir","sprite":{"peau":"#d9a27a","cheveux":"court","couleurCheveux":"#3a2a1a","haut":"#3a3f4a","accessoires":[]},"posture":"Parle fort, connaît tout le monde. Un peu trop bien intégré.","observer":{"texte":"Il tutoie les profs, sourit à tout le monde et connaît les prénoms des surveillants. Il les prononce avec soin, comme s'il les avait appris la veille.","indice":"nolan_prenoms"},"questions":[{"id":"q1","q":"T'es là depuis longtemps ?","r":"Depuis la seconde, grave. Je suis un ancien ici.","indice":"nolan_ancien"},{"id":"q2","q":"Pourquoi on appelle le proviseur « Monsieur Sourire » ?","r":"Euh... parce qu'il sourit tout le temps, non ?","indice":"nolan_sourire","requiert":"ines3_memoire"},{"id":"q3","q":"Tu te souviens des lasagnes, l'an dernier ?","r":"Les lasagnes ! Mortelles ! Elles étaient de la bombe, bébé. Le meilleur plat de la cantine, franchement.","indice":"nolan_lasagnes","requiert":"ines3_memoire"}],"fin":{"demasque":"{nolan} essaie de rire. Puis il comprend que personne ne rit avec lui. Il s'en va sans reprendre son sac. Dedans : un carnet de noms, et le mot « lasagnes » entouré d'un point d'interrogation.","sansPreuve":"« T'es parano. » {nolan} hausse les épaules. Sans preuve, le fumoir lui donne raison.","rate":"{nolan} connaît maintenant le surnom du proviseur, grâce à un élève qui a parlé sans réfléchir."},"grade":"Gardien de la paix Bernard, 26 ans","infiltre":true},{"id":"kenzo","nom":"{kenzo}","zone":"fumoir","infiltre":true,"condition":{"rateLaVeille":"kenzo"},"grade":"Brigadier Laurent, 34 ans","posture":"Même casquette, même sweat gris. Sa vape fume, et il tousse à chaque bouffée.","sprite":{"peau":"#e0b190","cheveux":"casquette","couleurCheveux":"#5b3a22","haut":"#4a6b4a","accessoires":["vape"]},"observer":{"texte":"Même sourire. Une vape qui fume vraiment, mais il tousse à chaque bouffée.","indice":"k3_toux"},"questions":[{"id":"q1","q":"Tu fais quoi, avec le portique ?","r":"Le portique ? Faut le contourner, non ? Vous avez un plan ? Dis-moi, je suis chaud.","indice":"k3_echange"},{"id":"q2","q":"Tu connais Monsieur Sourire ?","r":"Qui ? Le prof de sport ?","indice":"k3_sourire","requiert":"ines3_memoire"}],"fin":{"demasque":"{kenzo} ne dit rien, cette fois. Il écrase sa vape du talon et s'en va, tête haute. Il n'a plus rien à jouer.","sansPreuve":"{kenzo} rit, mais moins fort.","rate":"{kenzo} est toujours là. Sa vape fume, il tousse, et il écoute."}},{"id":"rayan","nom":"{rayan}","zone":"gymnase","sprite":{"peau":"#a86a4a","cheveux":"boucle","couleurCheveux":"#1a0f0a","haut":"#2a2a2a","accessoires":[]},"posture":"Veste en cuir neuve. Il l'essuie du coude à chaque fois qu'on la regarde.","observer":{"texte":"Veste de marque, neuve, sans le moindre pli. Il la porte comme un trophée.","indice":"rayan_veste"},"questions":[{"id":"q1","q":"Elle est neuve, ta veste ?","r":"Cadeau de ma grande sœur ! Son premier CDI. Elle me l'a donnée lundi, demande à {moussa}, je lui montre depuis deux jours.","indice":"rayan_alibi"},{"id":"q2","q":"Tu viens vendredi ?","r":"Évidemment. Ma sœur me dépose en voiture, elle veut voir ça. Elle se gare où elle peut, hein.","indice":"rayan_voiture"},{"id":"q3","q":"Tu connais Mme Okafor ?","requiert":"ines3_memoire","r":"Okafor ? SVT, prof principale des T2. Elle m'a collé une interro sur la cellule lundi. Tu crois que j'oublie ?","indice":"rayan_okafor_ok"}],"fin":{"accuseATort":"{rayan} arrête de porter sa veste. Sa sœur demande ce qui s'est passé. Il ne répond pas."},"infiltre":false},{"id":"dylan","nom":"{dylan}","zone":"gymnase","infiltre":true,"condition":{"rateLaVeille":"dylan"},"grade":"Gardien de la paix Morel, 29 ans","posture":"Il joue au hand, mal. Mêmes baskets blanches, même écouteur droit.","sprite":{"peau":"#d9a27a","cheveux":"rase","couleurCheveux":"#2a1a12","haut":"#1f2b5c","accessoires":["oreillette"]},"observer":{"texte":"Mêmes baskets blanches, qu'il astique entre deux passes. L'écouteur droit est toujours là, mais le fil ne va nulle part.","indice":"d3_barbe"},"questions":[{"id":"q1","q":"T'as quoi, comme cours, aujourd'hui ?","r":"Sport, comme tu vois. Et toi, le portique, tu comptes passer par où vendredi ?","indice":"d3_stagiaire"},{"id":"q2","q":"Tu connais Mme Okafor ?","r":"Okafor ? La prof de sport, non ? Super sympa.","indice":"d3_okafor","requiert":"ines3_memoire"}],"fin":{"demasque":"{dylan} arrache son écouteur : le fil ne mène nulle part. Il sort sans un mot, dans un silence de chapelle.","sansPreuve":"« Moi, un flic ? » {dylan} rit. Sans preuve, tu passes pour un obsédé.","rate":"{dylan} connaît maintenant tous les surnoms. Il les note."}},{"id":"sarah","nom":"{sarah}","zone":"cdi","infiltre":false,"posture":"Carnet ouvert, stylo mordillé. Elle relit un vieux numéro du Moulin.","sprite":{"peau":"#f0c8a8","cheveux":"chignon","couleurCheveux":"#a3502a","haut":"#2d5a3a","accessoires":["lunettes"]},"observer":{"texte":"Elle a retrouvé son article sur les lasagnes dans un vieux numéro du Moulin et le relit avec l'air de quelqu'un qui revient de loin."},"questions":[{"id":"q1","q":"L'association Prévention Jeunesse, tu connais ?","r":"J'ai vérifié : elle n'existe dans aucun registre de l'académie. Ni dans les partenaires du lycée, ni ailleurs.","indice":"sarah3_asso","requiert":"duval_asso"},{"id":"q2","q":"{nolan}, tu l'as déjà croisé ?","r":"Il m'a dit « salut {sarah} ! » le premier jour. Je ne le connaissais pas. Il connaissait mon prénom, mon nom, le nom de mon journal.","indice":"nolan_sarah"},{"id":"q3","q":"Tu penses à quoi, pour vendredi ?","r":"À ce que je vais écrire. Ce qu'ils auront fait, et ce qu'on aura fait.","gratuit":true}],"fin":{"accuseATort":"{sarah} range son carnet. Elle n'écrira plus sur le blocus. Le seul récit qui circule, c'est celui de la préfecture."}},{"id":"jade","nom":"{jade}","zone":"cdi","infiltre":true,"condition":{"rateLaVeille":"jade"},"grade":"Lieutenante Mercier, 27 ans","posture":"Elle lit un vrai roman, ouvert à la page 3 depuis une heure.","sprite":{"peau":"#c98e6a","cheveux":"long","couleurCheveux":"#3a2418","haut":"#6b2a8a","accessoires":["boucles"]},"observer":{"texte":"Elle a enlevé le stylo officiel. Mais son téléphone reste en mode avion, sans une notification, comme un téléphone de service.","indice":"j3_tel"},"questions":[{"id":"q1","q":"Tu lis quoi ?","r":"Un truc pour le bac. « L'Étranger », tu connais ?","indice":"j3_roman"},{"id":"q2","q":"Tu as Mme Okafor ?","r":"Okafor ? Oui, maths, non ? Super sympa.","indice":"j3_okafor","requiert":"ines3_memoire"}],"fin":{"demasque":"{jade} referme son livre. « Tu es doué. » Elle se lève, remet sa veste et sort. Cette fois, elle ne regarde personne.","sansPreuve":"{jade} te sourit avec pitié. « Tu es sûr que ça va ? » Sans preuve, c'est toi qui passes pour le paranoïaque.","rate":"{jade} déjeune maintenant avec les leaders. Elle apporte les cafés."}}],"epilogue":{"parfait":"Mercredi soir, plus personne ne copie personne. Les infiltrés qui restent savent qu'on les regarde. Inès sourit, pour la première fois depuis lundi. À 22h, un nouveau message du numéro anonyme : « Demain, ils changent de cible. Faites attention à vous. »","moyen":"Mercredi se termine avec des trous dans le groupe et des regards en coin. Quelque part, quelqu'un prépare quelque chose pour demain.","mauvais":"Le groupe est déchiré. Les infiltrés n'ont plus à se cacher : on fait le travail à leur place."}},"4":{"jour":4,"titre":"Jeudi. La rumeur.","intro":["Ce matin, des tracts imprimés sont collés dans tout le lycée. Titre : « LA BALANCE DU BLOCUS ». Dessous, une photo de {lucas}, et un texte qui l'accuse d'avoir donné l'heure à la police.","Le tract dit aussi que « quelqu'un du comité » l'a protégé, et que la mère de cette personne travaille au commissariat. Tout le monde regarde Inès.","Un tract en couleur comme ça, personne ne l'imprime au CDI. Quelqu'un veut que vous vous déchiriez avant vendredi. Et cette fois, personne n'est au-dessus des soupçons, pas même Inès.","Inès a reçu un message du même numéro anonyme : « Deux têtes de plus. Et un des vôtres a flanché. »"],"actions":11,"heureDebut":8,"minutesParAction":44,"zones":[{"id":"entree","nom":"Entrée","decor":"Des tracts sur les murs, par dizaines. Quelqu'un en arrache un, un autre le recolle."},{"id":"cantine","nom":"Cantine","decor":"Chacun mange en regardant son voisin. Personne ne s'assoit à côté d'Inès."},{"id":"fumoir","nom":"Fumoir","decor":"Des groupes de deux, qui se taisent quand tu passes."},{"id":"gymnase","nom":"Gymnase","decor":"Pas de cours. Des élèves assis par terre, les tracts dans les mains."},{"id":"cdi","nom":"CDI","decor":"La documentaliste a retiré un tract du panneau. Il est revenu une heure plus tard."}],"indices":{"ines3_memoire":{"texte":"Faits que seuls les élèves connaissent : les lasagnes périmées du 14 mars, Mme Okafor (SVT, prof principale des T2), le proviseur surnommé « Monsieur Sourire ».","type":"info"},"tract_mere":{"texte":"Le tract dit que la mère d'Inès travaille au commissariat.","type":"suspect","sur":"ines"},"tract_comite":{"texte":"Le tract accuse « quelqu'un du comité » d'avoir protégé {lucas}. Tout le monde pense à Inès.","type":"suspect","sur":"ines"},"ines4_mere":{"texte":"Inès : sa mère fait l'accueil au commissariat depuis dix ans. Elle l'a dit à tout le monde dès la sixième.","type":"innocent","sur":"ines"},"sarah4_ines":{"texte":"Sarah : mardi, après le blocus, Inès est restée avec elle au CDI jusqu'à midi. Elle n'a appelé personne.","type":"innocent","sur":"ines"},"chloe4_ines":{"texte":"Chloé : Inès a passé la nuit de lundi à tout organiser, et mardi elle était au premier rang.","type":"innocent","sur":"ines"},"lucas4_photo":{"texte":"La photo de Lucas sur le tract est prise de dos, devant l'entrée, mardi matin pendant le blocus.","type":"suspect","sur":"lucas"},"lucas4_alibi":{"texte":"{lucas} : il est resté devant la grille jusqu'à 10h avec les cadenas, avec {moussa}.","type":"innocent","sur":"lucas"},"moussa4_lucas":{"texte":"Moussa : mardi, au blocus, Lucas était à côté de lui jusqu'à 10h. Ils ont partagé un sandwich.","type":"innocent","sur":"lucas"},"photo_etage":{"texte":"La photo du tract est prise d'une fenêtre du couloir des profs, au premier étage.","type":"info"},"moussa4_papier":{"texte":"{moussa} : les tracts du blocus sont sur du papier recyclé. Celui-ci est sur un papier lourd, glacé.","type":"info"},"moussa4_provoc":{"texte":"Moussa : au comité, personne n'a parlé de brûler quoi que ce soit. Si quelqu'un le propose, ça ne vient pas de nous.","type":"info"},"sarah4_rolland":{"texte":"{sarah} : la psychologue du lycée, Mme Rolland, est là le mardi et le jeudi. Elle l'a croisée ce matin.","type":"info"},"sarah4_collectif":{"texte":"Le tract est signé « Le collectif des élèves ». Personne n'a jamais entendu parler de ce collectif.","type":"info"},"yanis4_rognage":{"texte":"{yanis} : le tract porte un point de rognage en coin, signe d'une imprimante professionnelle.","type":"info"},"chloe4_fille":{"texte":"Chloé a vu une fille avec un sac de sport coller des tracts dans les couloirs avant 8h, avant l'ouverture des portes.","type":"suspect","sur":"manon"},"manon_papier":{"texte":"Les tracts de {manon} sortent d'un paquet de papier lourd. Ceux du lycée sont pliés en quatre.","type":"suspect","sur":"manon"},"manon_grille":{"texte":"{manon} dit avoir trouvé les tracts devant la grille. Mais les tracts sont collés partout à l'intérieur, dès le matin.","type":"suspect","sur":"manon"},"manon_passe":{"texte":"{manon} distribue le tract en disant « il faut que tout le monde sache », avec un air choqué.","type":"suspect","sur":"manon"},"manon_couloir":{"texte":"{manon} dit être « allée dans le couloir des profs pour un papier ».","type":"suspect","sur":"manon"},"perrin_noms":{"texte":"M. Perrin note le nom de chaque élève qui entre dans sa salle.","type":"suspect","sur":"perrin"},"perrin_vendredi":{"texte":"M. Perrin demande qui parle de vendredi, « pour les protéger ». Un psychologue n'a pas à connaître l'organisation du blocus.","type":"suspect","sur":"perrin"},"perrin_rolland":{"texte":"M. Perrin dit remplacer Mme Rolland, « en arrêt ». {sarah} l'a croisée ce matin.","type":"suspect","sur":"perrin"},"leo_cartable":{"texte":"Léo n'a ni cartable ni cahier sur lui.","type":"suspect","sur":"leo"},"leo_provoc":{"texte":"{leo} propose de brûler une poubelle devant les policiers vendredi.","type":"suspect","sur":"leo"},"n4_nolan":{"texte":"Nolan a l'air de réciter une leçon sur l'histoire du lycée.","type":"suspect","sur":"nolan"},"n4_lasagnes":{"texte":"{nolan} a appris les lasagnes : il parle de « quarante et un malades ». Mais il dit « le 15 mars ».","type":"suspect","sur":"nolan"},"d4_asso":{"texte":"Mme Duval veut savoir qui a fait le tract contre Lucas.","type":"suspect","sur":"duval"},"d4_cordon":{"texte":"Mme Duval a remplacé son cordon par un lacet noir, mais le cordon bleu à liseré blanc de la police dépasse de sa poche.","type":"suspect","sur":"duval"},"b4_barbe":{"texte":"L'antenne du talkie de Bastien dépasse toujours de sa poche, et toujours pas de badge de la vie scolaire.","type":"suspect","sur":"bastien"},"b4_mairie":{"texte":"Bastien demande où le comité se réunit ce soir, « pour la sécurité ».","type":"suspect","sur":"bastien"},"j4_cheveux":{"texte":"Jade tourne les pages de son manuel sans les lire, toujours à l'envers.","type":"suspect","sur":"jade"},"j4_prof":{"texte":"Jade demande où le comité se retrouve vendredi : elle propose un local.","type":"suspect","sur":"jade"},"leo_comite_ok":{"texte":"Léo est dans le comité depuis septembre : il s'est laissé emporter, c'est tout.","type":"innocent","sur":"leo"},"yanis4_papier":{"texte":"Yanis a dans son sac une feuille vierge du même papier lourd que le tract.","type":"suspect","sur":"yanis"},"yanis4_pere":{"texte":"Yanis : son père travaille dans une imprimerie de la préfecture.","type":"suspect","sur":"yanis"},"yanis4_aveu":{"texte":"Yanis dit avoir « déjà vu ce papier dans le bureau de mon père... enfin, à l'imprimerie ».","type":"suspect","sur":"yanis"}},"pnj":[{"id":"ines","nom":"Inès","zone":"entree","infiltre":false,"posture":"Un tract à la main, assise seule sur le muret. Personne ne s'approche.","sprite":{"peau":"#a8704a","cheveux":"long","couleurCheveux":"#1b1210","haut":"#5a2a6b","accessoires":["boucles"]},"observer":{"texte":"Ses mains tremblent. Le tract est froissé, relu mille fois. Sa mère, dit le texte, travaille « au commissariat ».","indice":"tract_mere"},"questions":[{"id":"q1","q":"C'est toi qui as protégé {lucas} ?","r":"Je l'ai défendu parce qu'il n'a rien fait. C'est pas protéger.","indice":"tract_comite"},{"id":"q2","q":"Ta mère travaille bien au commissariat ?","r":"À l'accueil, depuis dix ans. Je l'ai dit à tout le monde dès la sixième. Jamais caché. Et tu crois que si j'étais une balance, je l'aurais dit ?","indice":"ines4_mere"},{"id":"q3","q":"Tu as peur ?","r":"Oui. Mais pas d'eux. De vous, maintenant.","gratuit":true}],"fin":{"accuseATort":"Inès te regarde un long moment. « Même toi. » Elle reste, parce que vendredi a besoin d'elle. Mais elle ne te dira plus rien."}},{"id":"manon","nom":"{manon}","zone":"entree","sprite":{"peau":"#f0c4a0","cheveux":"chignon","couleurCheveux":"#2a1a12","haut":"#2a2a3a","accessoires":["boucles"]},"posture":"Elle distribue le tract avec l'air choqué. Un paquet de feuilles dans le sac de sport.","observer":{"texte":"Dans son sac, deux piles : des tracts pliés en quatre, et un paquet de papier lourd, glacé, sorti de son emballage.","indice":"manon_papier"},"questions":[{"id":"q1","q":"Tu les as trouvés où, ces tracts ?","r":"Par terre, devant la grille ! Il y en avait plein.","indice":"manon_grille"},{"id":"q2","q":"C'est toi qui les distribues ?","r":"Moi ? Je les passe, c'est tout. Il faut que tout le monde sache.","indice":"manon_passe"},{"id":"q3","q":"La photo est prise du couloir des profs. Tu y as accès ?","r":"Moi ? Euh... j'y suis allée pour... un papier. Un truc de la vie scolaire.","indice":"manon_couloir","requiert":"photo_etage"}],"fin":{"demasque":"{manon} laisse tomber les tracts. Le vent les disperse. Elle quitte le lycée à pied, très vite, vers une voiture déjà en marche.","sansPreuve":"« Je les ai juste trouvés ! » Sans preuve, on la croit : elle pleure presque. Tu es seul.","rate":"Les tracts de {manon} ont fait leur travail. À midi, Inès et {lucas} ne se parlent plus."},"grade":"Gardienne de la paix Lemoine, 24 ans","infiltre":true},{"id":"moussa","nom":"{moussa}","zone":"cantine","infiltre":false,"posture":"Il lit le tract en entier, ligne par ligne, comme s'il corrigeait une copie.","sprite":{"peau":"#4a2e20","cheveux":"court","couleurCheveux":"#0e0a08","haut":"#b33a2a","accessoires":[]},"observer":{"texte":"Il a posé trois tracts côte à côte sur la table et compare les polices."},"questions":[{"id":"q1","q":"Tu vois d'où il vient, ce tract ?","r":"Pas de chez nous. Les nôtres sont sur du recyclé. Celui-là, papier lourd, glacé, imprimé pro. Quelqu'un a de l'argent derrière.","indice":"moussa4_papier"},{"id":"q2","q":"{lucas}, tu lui fais confiance ?","r":"Mardi, au blocus, on était côte à côte jusqu'à 10h. On a partagé un sandwich. S'il avait appelé quelqu'un, je l'aurais vu.","indice":"moussa4_lucas"},{"id":"q3","q":"Et pour vendredi ?","r":"Au comité, personne n'a parlé de brûler quoi que ce soit. Si quelqu'un te le propose, méfie-toi : ça ne vient pas de nous.","indice":"moussa4_provoc"}],"fin":{"accuseATort":"{moussa} te regarde, silencieux. Puis il vide son sac de classe et rend ses clés du local. « On n'a plus besoin de moi. »"}},{"id":"perrin","nom":"M. Perrin","zone":"cdi","infiltre":true,"grade":"Commandant Perrin, 46 ans, renseignement territorial","posture":"Veste de laine, carnet ouvert. Il propose d'« écouter » ceux que le tract a troublés.","sprite":{"peau":"#e8c0a0","cheveux":"rase","couleurCheveux":"#7a7a7a","haut":"#6b5a3a","accessoires":["lunettes"]},"observer":{"texte":"Il a une salle réservée par la direction. Il note le nom de chaque élève qui y entre, d'un geste très appliqué.","indice":"perrin_noms"},"questions":[{"id":"q1","q":"Vous êtes là pour qui ?","r":"Pour ceux qui ont peur. Personne ne doit rester seul avec ça. Qui vous a fait peur ? Qui parle de vendredi ?","indice":"perrin_vendredi"},{"id":"q2","q":"La psychologue, c'est Mme Rolland, non ?","r":"Mme Rolland est en arrêt. C'est moi qui la remplace.","indice":"perrin_rolland","requiert":"sarah4_rolland"}],"fin":{"demasque":"M. Perrin referme son carnet avec une grande douceur. « Je comprends. » Dans le couloir, il croise le proviseur, et ne le salue pas.","sansPreuve":"« Je suis juste là pour aider. » Sans preuve, le groupe te trouve injuste.","rate":"M. Perrin a reçu dix-sept élèves aujourd'hui. Il a dix-sept noms, dix-sept confidences."}},{"id":"leo","nom":"{leo}","zone":"fumoir","sprite":{"peau":"#c98e6a","cheveux":"capuche","couleurCheveux":"#151515","haut":"#1a2a1a","accessoires":[]},"posture":"Capuche, énervé. Il parle fort de « faire un truc dur » vendredi.","observer":{"texte":"Il n'a ni cartable ni cahier. Il parle fort et vite, comme quelqu'un qui n'a pas dormi.","indice":"leo_cartable"},"questions":[{"id":"q1","q":"Tu veux faire quoi, vendredi ?","r":"Un truc qui claque ! On crame une poubelle devant les keufs, ça va leur faire peur. Mais Moussa dit que c'est une mauvaise idée. T'en penses quoi ?","indice":"leo_provoc"},{"id":"q2","q":"Le comité est d'accord ?","r":"Le comité ? J'y suis depuis septembre. {moussa} m'a dit qu'on brûle rien. J'ai crash out, c'est tout. Je me suis laissé emporter.","indice":"leo_comite_ok","requiert":"moussa4_provoc"}],"fin":{"accuseATort":"Léo, qui s'était seulement laissé emporter, est mis à la porte du comité par ceux qu'il voulait défendre. Vendredi, il ne vient pas."},"infiltre":false},{"id":"chloe","nom":"{chloe}","zone":"fumoir","infiltre":false,"reserve":true,"posture":"Dos au mur, tract déchiré à la main.","sprite":{"peau":"#f2d0b5","cheveux":"capuche","couleurCheveux":"#151515","haut":"#111111","accessoires":["boucles"]},"observer":{"texte":"Elle a déchiré le tract en confettis et les jette un à un sur la tête de ceux qui passent."},"questions":[{"id":"q1","q":"T'as vu qui collait les tracts ?","r":"Une fille, avant 8h, avec un sac de sport. Elle collait déjà dans les couloirs alors que les portes n'ouvrent qu'à 8h. Je me suis demandé comment elle était entrée.","indice":"chloe4_fille"},{"id":"q2","q":"Tu penses qu'Inès a balancé ?","r":"Inès a passé la nuit de lundi au téléphone pour que tout soit prêt. Mardi, elle était au premier rang. Les balances, ça fait pas ça. T'es paro, là.","indice":"chloe4_ines"}],"fin":{"accuseATort":"Chloé quitte le fumoir. Sur le mur, elle écrit à la bombe : « ON SE DÉNONCE ENTRE NOUS. ILS N'ONT PLUS RIEN À FAIRE. » Vendredi, elle viendra, mais seule."}},{"id":"lucas","nom":"{lucas}","zone":"gymnase","infiltre":false,"posture":"Assis seul, la photo du tract froissée dans le poing.","sprite":{"peau":"#e8b896","cheveux":"court","couleurCheveux":"#c49a4a","haut":"#d4a017","accessoires":[]},"observer":{"texte":"Il tient la photo du tract : prise de dos, devant l'entrée, mardi matin, pendant le blocus. On ne voit pas qui l'a prise.","indice":"lucas4_photo"},"questions":[{"id":"q1","q":"C'est vrai ce qu'ils disent ?","r":"Moi ? Mardi, je suis resté devant la grille jusqu'à 10h, avec les cadenas. Demande à {moussa}, on a bloqué ensemble. Wallah.","indice":"lucas4_alibi"},{"id":"q2","q":"Qui a pu prendre la photo ?","r":"Elle est prise de dedans, au premier étage, par les fenêtres du couloir des profs. Là où on n'a pas le droit d'aller.","indice":"photo_etage"}],"fin":{"accuseATort":"{lucas} rend les cadenas à Inès, un par un, sans un mot. Il ne lui reste plus personne. Ceux qui cherchent des élèves seuls, eux, l'ont remarqué."}},{"id":"sarah","nom":"{sarah}","zone":"cdi","infiltre":false,"posture":"Elle examine le tract à la loupe, côté pile, côté face.","sprite":{"peau":"#f0c8a8","cheveux":"chignon","couleurCheveux":"#a3502a","haut":"#2d5a3a","accessoires":["lunettes"]},"observer":{"texte":"Elle a posé le tract sur la table lumineuse du CDI, et repère quelque chose dans le grain du papier."},"questions":[{"id":"q1","q":"T'as vu Inès, mardi ?","r":"Après le blocus, elle est restée avec moi au CDI jusqu'à midi. Elle n'a appelé personne, j'étais à côté.","indice":"sarah4_ines"},{"id":"q2","q":"Qui signe « Le collectif des élèves » ?","r":"Personne. Aucun collectif de ce nom n'existe dans le lycée. Il a été inventé pour cette feuille.","indice":"sarah4_collectif"},{"id":"q4","q":"Qu'est-ce que tout le monde sait ici, et personne d'ailleurs ?","r":"Les lasagnes du 14 mars. Mme Okafor, notre prof de SVT. Et le proviseur, qu'on appelle Monsieur Sourire parce qu'il ne sourit jamais. Ça, un élève le sait depuis la seconde.","indice":"ines3_memoire"},{"id":"q3","q":"La psychologue du lycée, tu l'as vue ?","r":"Mme Rolland ? Je l'ai croisée ce matin. Elle est là le mardi et le jeudi.","indice":"sarah4_rolland"}],"fin":{"accuseATort":"{sarah} range son carnet. « Je vous ai défendus toute la semaine. » Vendredi, elle viendra pour regarder, plus pour vous."}},{"id":"yanis","nom":"{yanis}","zone":"cdi","sprite":{"peau":"#6b4530","cheveux":"boucle","couleurCheveux":"#120c0a","haut":"#24486b","accessoires":["lunettes"]},"posture":"Il compare le tract à une feuille sortie de son sac.","observer":{"texte":"Il a posé le tract à côté d'une feuille vierge sortie de son sac. Même papier lourd, même grain. Il la range dès qu'il te voit.","indice":"yanis4_papier"},"questions":[{"id":"q1","q":"Le tract vient d'où, à ton avis ?","r":"Regarde le coin : il y a un petit point de rognage. Ça vient d'une imprimante professionnelle, pas d'un photocopieur de lycée.","indice":"yanis4_rognage"},{"id":"q2","q":"Tu t'y connais en imprimantes ?","r":"Un peu. Mon père bosse dans une imprimerie de la préfecture.","indice":"yanis4_pere"},{"id":"q3","q":"Comment tu sais que c'est un papier pro ?","r":"J'ai déjà vu ce papier dans le bureau de mon père... enfin, à l'imprimerie.","indice":"yanis4_aveu","requiert":"yanis4_rognage"}],"fin":{"demasque":"{yanis} ne proteste pas. « Ils ont dit que mon dossier de bourse pouvait se perdre. Et que mon père, à l'imprimerie, pouvait perdre sa place. » Il pose la feuille sur la table. Inès s'assoit à côté de lui, et personne ne le chasse.","sansPreuve":"« Moi ? » {yanis} a l'air blessé. Sans preuve, tu blesses quelqu'un qui en porte déjà trop.","rate":"Ce soir, {yanis} envoie un message à un numéro sans nom : qui a collé quoi, et qui a protégé qui."},"grade":"{yanis}, 16 ans, vrai élève sous pression","infiltre":true,"balance":true},{"id":"nolan","nom":"{nolan}","zone":"fumoir","infiltre":true,"condition":{"rateLaVeille":"nolan"},"grade":"Gardien de la paix Bernard, 26 ans","posture":"Il parle fort, connaît tout le monde. Toujours « un ancien » du lycée.","sprite":{"peau":"#d9a27a","cheveux":"court","couleurCheveux":"#3a2a1a","haut":"#3a3f4a","accessoires":[]},"observer":{"texte":"Il tutoie tout le monde. Il parle des lasagnes en connaisseur et il a appris la date par cœur. Presque.","indice":"n4_nolan"},"questions":[{"id":"q1","q":"Les lasagnes, c'était quand ?","r":"Le 15 mars. Quarante et un malades. Tout le lycée s'en souvient.","indice":"n4_lasagnes","requiert":"ines3_memoire"}],"fin":{"demasque":"{nolan} hausse les épaules : « Vous perdez votre temps. » Mais il se retourne, une dernière fois, en sortant.","sansPreuve":"« Moi, un flic ? Vous voyez des flics partout. » Il a l'air blessé. Sans preuve, tu as l'air ridicule.","rate":"{nolan} connaît maintenant tous les surnoms du lycée. Il les note."}},{"id":"duval","nom":"Mme Duval","zone":"entree","infiltre":true,"condition":{"rateLaVeille":"duval"},"grade":"Capitaine Duval, 41 ans","posture":"Même blazer beige, mêmes brochures. Même sourire pour tous les lycéens.","sprite":{"peau":"#f0c8a8","cheveux":"long","couleurCheveux":"#7a5a3a","haut":"#8a6a4a","accessoires":["lunettes"]},"observer":{"texte":"Elle a remplacé son cordon bleu par un lacet noir. Mais l'ancien, bleu à liseré blanc, dépasse de sa poche.","indice":"d4_cordon"},"questions":[{"id":"q1","q":"Vous êtes encore là ?","r":"Je reviens tant que les lycéens ont besoin de nous. Dites-moi, c'est vrai qu'un tract circule contre un élève ? Qui l'a fait ?","indice":"d4_asso"}],"fin":{"demasque":"Mme Duval sourit : « Vous êtes très perspicace. » Elle laisse ses brochures et traverse la cour sans se presser.","sansPreuve":"« Moi, une flic ? » Sans preuve, tu passes pour un obsédé.","rate":"Mme Duval a rencontré le proviseur ce matin. Les nouvelles règles de vendredi sont déjà sur son bureau."}},{"id":"bastien","nom":"Bastien","zone":"entree","infiltre":true,"condition":{"rateLaVeille":"bastien"},"grade":"Brigadier-chef Faure, 31 ans","posture":"Même sourire large. L'antenne du talkie dépasse toujours de sa poche.","sprite":{"peau":"#e8c0a0","cheveux":"rase","couleurCheveux":"#6b4a2a","haut":"#3a4a2a","accessoires":[]},"observer":{"texte":"L'antenne du talkie noir dépasse de sa poche, comme mardi. Toujours pas de badge autour du cou.","indice":"b4_barbe"},"questions":[{"id":"q1","q":"Tu fais quoi, ici, aujourd'hui ?","r":"Je surveille la cour, comme d'hab. Dis-moi, le comité se réunit où, ce soir ? Je pourrais passer, pour la sécurité.","indice":"b4_mairie"}],"fin":{"demasque":"Bastien lève les mains. « OK. OK. » Il part en marchant, très droit, vers une voiture dont le coffre est déjà ouvert.","sansPreuve":"« Moi, un flic ? » Il rit. Sans preuve, c'est toi qui es embarrassé.","rate":"Bastien a passé la semaine à surveiller sans que personne ne l'arrête."}},{"id":"jade","nom":"{jade}","zone":"cdi","infiltre":true,"condition":{"rateLaVeille":"jade"},"grade":"Lieutenante Mercier, 27 ans","posture":"Même manuel, toujours à l'envers. Même téléphone en mode avion.","sprite":{"peau":"#c98e6a","cheveux":"court","couleurCheveux":"#a02a2a","haut":"#3a2a6b","accessoires":["boucles"]},"observer":{"texte":"Elle tourne les pages de son manuel sans les lire, toujours à l'envers. Tu commences à croire que c'est volontaire.","indice":"j4_cheveux"},"questions":[{"id":"q1","q":"Tu fais quoi, au CDI, tout le temps ?","r":"Je révise. Dis, il paraît qu'Inès cherche un local pour vendredi ? Je peux en proposer un.","indice":"j4_prof"}],"fin":{"demasque":"{jade} referme le manuel à l'endroit, cette fois. « Bien joué. » Elle te serre la main. Puis elle part.","sansPreuve":"{jade} te regarde avec une pitié sincère. Sans preuve, le groupe te trouve pénible.","rate":"{jade} a maintenant une copine, au fumoir, qui lui raconte tout."}}],"epilogue":{"parfait":"Ce soir, les tracts sont dans les poubelles. {lucas} et Inès parlent à nouveau. Mais un dernier tract tombe de la porte de {moussa} : « Vendredi, vous verrez. »","moyen":"Jeudi soir, la rumeur a laissé des traces. Certains ne parlent plus à d'autres. Vendredi se prépare dans une ambiance de méfiance.","mauvais":"Le comité est dissous. Plus personne ne sait qui croire. Le tract a fait le travail de dix flics."}},"5":{"jour":5,"titre":"Vendredi. Le blocus.","intro":["Il est 5h40 et il fait encore nuit. Dans moins de deux heures, à 7h30, trois lycées bloqueront en même temps : le vôtre, Camus et Pasteur. Une voiture banalisée attend déjà devant la grille. Quelqu'un a donné l'heure.","Inès a supprimé le groupe WhatsApp. Il ne reste que ceux qui sont là, maintenant, sous les lampadaires.","Dernier message du numéro anonyme, reçu à 5h : « Deux inconnus devant la grille. Un des vôtres leur a tout dit. » C'est ta dernière chance : tu as jusqu'à 7h30, et ceux qui restent sont les mieux préparés de la semaine."],"actions":11,"heureDebut":5.666666666666667,"minutesParAction":10,"zones":[{"id":"entree","nom":"Devant la grille","decor":"Les cadenas sont en place. Les poubelles sont empilées. Il reste deux heures."},{"id":"cantine","nom":"Sous le préau","decor":"Café fumant et banderoles pliées. Les élèves de Camus et Pasteur arrivent."},{"id":"fumoir","nom":"Rue de derrière","decor":"Une rue étroite, une voiture grise à moitié garée. Tout le monde regarde dans sa direction."},{"id":"gymnase","nom":"Portail du gymnase","decor":"La grille de derrière, la plus faible. C'est là qu'ils attaqueront."},{"id":"cdi","nom":"Toit du CDI","decor":"On voit toute la cour d'ici. Et le toit des voitures."}],"indices":{"ines5_enjeu":{"texte":"Inès : trois lycées, quatre cents personnes. Si un infiltré reste, ce ne sont plus des noms dans une liste mais des gens dans un fourgon.","type":"info"},"ines5_delegues":{"texte":"Inès : {anais} est la déléguée de Camus. {nina} dit venir de Camus aussi.","type":"info"},"nina_moussa":{"texte":"Moussa connaît les élèves de Camus. Anaïs lui a dit que ses quarante sont arrivés ensemble : pas de Nina.","type":"suspect","sur":"nina"},"nina_anais":{"texte":"{anais}, déléguée de Camus, dit n'avoir jamais vu {nina}.","type":"suspect","sur":"nina"},"nina_sac":{"texte":"Le sac de Nina porte un autocollant « Camus » flambant neuf, collé sur un sac usé. Sa pancarte est neuve, jamais pliée.","type":"suspect","sur":"nina"},"nina_aveu":{"texte":"Quand on lui dit qu'{anais} ne la connaît pas, {nina} répond « je suis nouvelle », puis change de sujet.","type":"suspect","sur":"nina"},"duret_fils":{"texte":"Un homme en blouson dit chercher son fils en seconde, sans dire son prénom.","type":"info"},"duret_oreillette":{"texte":"L'homme au blouson a une oreillette discrète à l'oreille droite et ne regarde jamais les visages, seulement les mains.","type":"suspect","sur":"duret"},"duret_telephones":{"texte":"{sarah} : l'homme au blouson regarde les téléphones, pas les gens.","type":"suspect","sur":"duret"},"duret_aveu":{"texte":"Interrogé sur le prénom de son fils : « {theo}. Non, Karim. Je veux dire... »","type":"suspect","sur":"duret"},"hugo_visages":{"texte":"Hugo photographie les visages en gros plan, un par un, avec un appareil tout neuf.","type":"suspect","sur":"hugo"},"m5_papier":{"texte":"Manon distribue encore le tract d'hier, imprimé sur du papier lourd et glacé, pas sur le papier du lycée.","type":"suspect","sur":"manon"},"m5_coupe":{"texte":"Manon dit n'avoir jamais entendu parler de Lucas. Le tract d'hier portait son nom et sa photo.","type":"suspect","sur":"manon"},"p5_badge":{"texte":"M. Perrin note encore les noms de ceux qui passent, avec le même carnet.","type":"suspect","sur":"perrin"},"p5_noms":{"texte":"M. Perrin lit à haute voix les noms qu'il a notés hier, comme s'il les testait.","type":"suspect","sur":"perrin"},"d5_asso":{"texte":"Mme Duval regarde chaque élève qui arrive, sans plus parler de prévention.","type":"suspect","sur":"duval"},"d5_fils":{"texte":"Moussa : l'association de Mme Duval ne vient jamais à 5h40 du matin devant un blocus.","type":"suspect","sur":"duval"},"chloe5_ines":{"texte":"{chloe} : Inès a gardé son téléphone éteint depuis hier soir pour qu'on ne la trace pas.","type":"info"},"hugo_fixe":{"texte":"Hugo : étudiant en photojournalisme, le reportage est pour son mémoire. Il propose de flouter les visages.","type":"innocent","sur":"hugo"},"hugo_carte_vraie":{"texte":"La carte d'étudiant de Hugo est valide : hologramme, école de journalisme, numéro vérifiable.","type":"innocent","sur":"hugo"},"chloe_hugo_ok":{"texte":"Chloé : Hugo lui a demandé si elle voulait être floutée sur la photo. Un vrai photographe demande ça.","type":"innocent","sur":"hugo"},"sarah_hugo_ok":{"texte":"Sarah : Hugo est étudiant en journalisme, sa carte est vraie. Elle a appelé l'école.","type":"innocent","sur":"hugo"},"lucas5_ouvert":{"texte":"Lucas a enroulé la chaîne de la grille de derrière sans verrouiller le cadenas.","type":"suspect","sur":"lucas"},"lucas5_rien":{"texte":"Lucas affirme n'avoir vu aucun adulte, alors que le monsieur au blouson est devant la grille.","type":"suspect","sur":"lucas"},"lucas5_aveu":{"texte":"Lucas dit fermer le cadenas « à la fin ». Un cadenas ouvert, ça ne bloque rien.","type":"suspect","sur":"lucas"},"anais_pied":{"texte":"Anaïs : les quarante de Camus sont venus à pied, sans sac. C'était la consigne.","type":"info"},"nina_bus":{"texte":"Nina dit être venue de Camus en bus, avec les autres.","type":"suspect","sur":"nina"},"d5_resp":{"texte":"Mme Duval veut savoir qui est responsable du blocus.","type":"suspect","sur":"duval"}},"pnj":[{"id":"ines","nom":"Inès","zone":"entree","infiltre":false,"allie":true,"posture":"Le téléphone éteint. Elle regarde la rue d'un air déterminé.","sprite":{"peau":"#a8704a","cheveux":"long","couleurCheveux":"#1b1210","haut":"#5a2a6b","accessoires":["boucles"]},"observer":{"texte":"Elle tient la banderole d'une main et le talkie des organisateurs de l'autre. Elle a l'air plus vieille que lundi."},"questions":[{"id":"q1","q":"On est prêts ?","r":"Trois lycées, quatre cents personnes. Si un infiltré reste, ce ne sont plus des noms sur une liste, mais des gens dans un fourgon. Prends ton temps. Mais pas trop.","indice":"ines5_enjeu"},{"id":"q2","q":"Qui est venu d'ailleurs ?","r":"{anais}, la déléguée de Camus, est arrivée la première avec quarante élèves. Une autre fille, {nina}, dit venir de Camus aussi. Demande à {moussa}, il connaît les deux lycées.","indice":"ines5_delegues"},{"id":"q3","q":"Et toi, ça va ?","r":"Je ne sais pas. Je sais juste qu'on est là.","gratuit":true}]},{"id":"duret","nom":"Le monsieur au blouson","zone":"entree","infiltre":true,"grade":"Commissaire divisionnaire Duret, 52 ans","posture":"Blouson noir, chaussures de ville. Il dit chercher son fils.","sprite":{"peau":"#d9a27a","cheveux":"rase","couleurCheveux":"#2a2a2a","haut":"#1a1a22","accessoires":["oreillette"]},"observer":{"texte":"Blouson noir, jean propre, chaussures de cuir de ville. Une oreillette discrète à l'oreille droite. Il ne regarde jamais les visages, seulement les mains.","indice":"duret_oreillette"},"questions":[{"id":"q1","q":"Vous cherchez quelqu'un ?","r":"Mon fils. Il est en seconde. Je voulais juste m'assurer qu'il allait bien.","indice":"duret_fils"},{"id":"q2","q":"Comment il s'appelle, votre fils ?","r":"Ah... {theo}. Non, Karim. Je veux dire...","indice":"duret_aveu","requiert":"duret_fils"}],"fin":{"demasque":"Le monsieur au blouson ne nie pas. Il ouvre la main : une carte tricolore. « C'est exact. » Il parle à son poignet. Les voitures grises, derrière, démarrent.","sansPreuve":"« Un policier ? Je suis père de famille ! » Les adultes autour de lui s'indignent. Sans preuve, c'est toi qui es dehors.","rate":"À 7h30, le monsieur au blouson donne un signal. Les voitures grises ne perdent pas une seconde."}},{"id":"moussa","nom":"{moussa}","zone":"cantine","infiltre":false,"posture":"Il regarde les élèves de Camus, un par un.","sprite":{"peau":"#4a2e20","cheveux":"court","couleurCheveux":"#0e0a08","haut":"#b33a2a","accessoires":[]},"observer":{"texte":"Il a fait un tour du préau pour voir qui vient de Camus. Il reconnaît tout le monde, sauf une fille."},"questions":[{"id":"q1","q":"Tu connais {nina} ?","r":"Nina de Camus ? J'ai fait le collège avec la moitié de Camus, et Anaïs m'a dit que ses quarante sont arrivés ensemble. Pas de Nina.","indice":"nina_moussa","requiert":"ines5_delegues"},{"id":"q2","q":"Une femme au blazer beige, tu la connais ?","r":"La dame avec les brochures ? Prévention Jeunesse, ils viennent le mercredi après-midi, jamais à 5h40 du matin devant un blocus. Pourquoi elle est là à cette heure ?","indice":"d5_fils","requiert":"d5_asso"},{"id":"q3","q":"On y va ?","r":"On y est.","gratuit":true}],"fin":{"accuseATort":"{moussa} lâche la banderole. « J'ai plus de goût à ça. » Il part vers le bus. La grille tiendra un peu moins bien."}},{"id":"anais","nom":"{anais}","zone":"cantine","infiltre":false,"posture":"Déléguée de Camus, mégaphone à la main. Elle surveille ses troupes.","sprite":{"peau":"#f0c4a0","cheveux":"long","couleurCheveux":"#3a2a1a","haut":"#c4a02a","accessoires":[]},"observer":{"texte":"Elle tient son mégaphone, a des cernes et pas de patience. Elle ne quitte pas ses troupes des yeux."},"questions":[{"id":"q1","q":"{nina} vient bien de chez vous ?","r":"{nina} ? Non. J'ai jamais vu cette fille. Elle a débarqué avec nos pancartes dans les mains, mais on n'en avait pas fait de cette taille.","indice":"nina_anais","requiert":"ines5_delegues"},{"id":"q2","q":"Vous êtes combien ?","r":"Quarante. On est venus à pied depuis Camus, partis à 5h. Personne n'a de sac, c'était la consigne.","gratuit":true,"indice":"anais_pied"}],"fin":{"accuseATort":"{anais} reprend son mégaphone et rappelle ses élèves. « On repart. On vous laisse. » Le front se brise à trois."}},{"id":"nina","nom":"{nina}","zone":"fumoir","sprite":{"peau":"#e0b190","cheveux":"boucle","couleurCheveux":"#3a2418","haut":"#a02a2a","accessoires":[]},"posture":"Pancarte neuve, trop grande, jamais pliée. Elle dit venir de Camus.","observer":{"texte":"La pancarte est trop grande pour avoir été faite par des élèves. L'autocollant « Camus » sur son sac vient d'être collé : il est tout neuf, sur un sac usé.","indice":"nina_sac"},"questions":[{"id":"q1","q":"T'es de Camus ?","r":"Ouais, terminale. On est venus en bus. Ça va être chanmé, ce blocus, on va tout déchirer, ma gueule !","indice":"nina_bus"},{"id":"q2","q":"{anais} dit qu'elle ne te connaît pas.","r":"Je suis... nouvelle. Écoute, pas maintenant.","indice":"nina_aveu","requiert":"nina_anais"}],"fin":{"demasque":"{nina} plie sa pancarte, lentement. « Bon. » Elle sourit, presque soulagée, et s'éloigne vers le bout de la rue.","sansPreuve":"« Je viens de Camus, je te le jure ! » Sans preuve, la foule de Camus hésite. {anais} ne dit rien.","rate":"{nina} a rejoint le cordon des premiers rangs. Elle donnera le signal à 7h30."},"grade":"Gardienne de la paix Roche, 25 ans","infiltre":true},{"id":"chloe","nom":"{chloe}","zone":"fumoir","infiltre":false,"reserve":true,"posture":"Capuche relevée, poing serré. Elle n'a pas peur : c'est pire.","sprite":{"peau":"#f2d0b5","cheveux":"capuche","couleurCheveux":"#151515","haut":"#111111","accessoires":["boucles"]},"observer":{"texte":"Elle surveille la voiture grise sans cligner des yeux."},"questions":[{"id":"q2","q":"Et Inès ?","r":"Elle a coupé son téléphone depuis hier soir, pour ne pas se faire tracer. Elle est plus maligne que nous tous.","indice":"chloe5_ines"},{"id":"q1b","q":"Tu as vu quelqu'un de bizarre ?","r":"Personne. Le photographe, {hugo}, m'a demandé si je voulais être floutée. C'est le seul qui m'ait demandé quelque chose.","indice":"chloe_hugo_ok"}],"fin":{"accuseATort":"{chloe} retire sa capuche et regarde la rue. « Ils n'avaient pas besoin de vous. » Elle s'en va avant 7h."}},{"id":"hugo","nom":"{hugo}","zone":"fumoir","sprite":{"peau":"#e8c0a0","cheveux":"court","couleurCheveux":"#4a3a2a","haut":"#3a4a5a","accessoires":["lunettes"]},"posture":"« Étudiant en photojournalisme ». Appareil neuf en bandoulière.","observer":{"texte":"Un appareil photo neuf, encore tout propre. Il photographie les visages en gros plan, un par un, mais demande d'abord : « Je peux ? »","indice":"hugo_visages"},"questions":[{"id":"q1","q":"Tu bosses pour qui ?","r":"Pour moi. Je suis en école de photojournalisme, ce reportage, c'est mon mémoire. Tu veux que je floute ton visage ? Je peux.","indice":"hugo_fixe"},{"id":"q2","q":"Montre-moi ta carte de presse.","r":"La voilà. Carte d'étudiant de l'école de journalisme, avec hologramme. Le numéro de l'école est derrière, appelle si tu veux.","indice":"hugo_carte_vraie","apres":["q1"]}],"fin":{"accuseATort":"Hugo range son appareil. « Je voulais juste témoigner. » Son reportage ne sort jamais."},"infiltre":false},{"id":"lucas","nom":"{lucas}","zone":"gymnase","sprite":{"peau":"#e8b896","cheveux":"court","couleurCheveux":"#c49a4a","haut":"#d4a017","accessoires":[]},"posture":"Il vérifie les chaînes, une par une, sans un mot.","observer":{"texte":"Il enroule la chaîne autour de la grille de derrière. Le cadenas pend, mais il ne l'a pas verrouillé : il suffit de le décrocher pour que la grille s'ouvre.","indice":"lucas5_ouvert"},"questions":[{"id":"q1","q":"Tu as vu des adultes ?","r":"Non, rien. Personne. Tout est calme.","indice":"lucas5_rien"},{"id":"q2","q":"Pourquoi tu ne fermes pas le cadenas ?","r":"Je le ferme à la fin, quand tout le monde est là. Sinon on perd du temps.","indice":"lucas5_aveu","requiert":"lucas5_ouvert"}],"fin":{"demasque":"Lucas lâche la chaîne. « Après le tract, ils m'ont dit qu'ils pouvaient me laver. Ou me couler. » Personne ne le frappe. Moussa reprend le cadenas, doucement.","sansPreuve":"« Le cadenas ? Je le ferme à la fin ! » Sans preuve, le groupe le croit. La grille de derrière reste fragile.","rate":"À 7h35, la grille de derrière s'ouvre d'un seul geste : tous les cadenas étaient ouverts."},"grade":"{lucas}, 17 ans, vrai élève sous pression","infiltre":true,"balance":true},{"id":"sarah","nom":"{sarah}","zone":"cdi","infiltre":false,"posture":"Carnet ouvert, appareil photo en bandoulière. Elle couvre l'événement.","sprite":{"peau":"#f0c8a8","cheveux":"chignon","couleurCheveux":"#a3502a","haut":"#2d5a3a","accessoires":["lunettes"]},"observer":{"texte":"Elle porte un brassard « Journal du lycée » cousu main et un vrai appareil photo, bosselé."},"questions":[{"id":"q2","q":"Tu écris quoi, aujourd'hui ?","r":"Le récit de la semaine. Pour qu'il y en ait un autre que celui de la préfecture.","gratuit":true},{"id":"q1b","q":"Le photographe, {hugo}, tu le connais ?","r":"{hugo} ? Il est en école de journalisme. Sa carte d'étudiant est vraie : hologramme, numéro, tout. J'ai appelé l'école.","indice":"sarah_hugo_ok"},{"id":"q3","q":"Tu vois des adultes qu'on ne connaît pas ?","r":"Le monsieur en blouson, devant. Je l'ai pris en photo trois fois : il regarde les téléphones, jamais les gens.","indice":"duret_telephones"}],"fin":{"accuseATort":"{sarah} range son appareil. Son récit de la semaine est resté dans un tiroir. Il n'y a plus que celui de la préfecture."}},{"id":"manon","nom":"{manon}","zone":"entree","infiltre":true,"condition":{"rateLaVeille":"manon"},"grade":"Gardienne de la paix Lemoine, 24 ans","posture":"Elle est revenue avec son sac de sport, un paquet de tracts à la main. Elle a l'air choquée.","sprite":{"peau":"#f0c4a0","cheveux":"chignon","couleurCheveux":"#2a1a12","haut":"#c4c4c4","accessoires":["boucles"]},"observer":{"texte":"Même sac de sport, même papier lourd et glacé : elle distribue encore le tract d'hier, avec un air choqué.","indice":"m5_papier"},"questions":[{"id":"q1","q":"Tu connais {lucas} ?","r":"Qui ? {lucas} ? Jamais entendu parler.","indice":"m5_coupe"}],"fin":{"demasque":"{manon} laisse tomber les feuilles. Elle a une expression d'enfant pris sur le fait. Puis elle part en courant.","sansPreuve":"{manon} éclate en sanglots, très convaincante. Sans preuve, on la console.","rate":"{manon} a obtenu les excuses publiques d'Inès, devant tout le monde."}},{"id":"perrin","nom":"M. Perrin","zone":"cdi","infiltre":true,"condition":{"rateLaVeille":"perrin"},"grade":"Commandant Perrin, 46 ans","posture":"Même veste de laine, même carnet. Il propose toujours d'« écouter » ceux qui ont peur.","sprite":{"peau":"#e8c0a0","cheveux":"rase","couleurCheveux":"#7a7a7a","haut":"#4a4a4a","accessoires":["lunettes"]},"observer":{"texte":"Même veste de laine, même carnet : il note les noms de ceux qui passent, d'un geste appliqué. La même voix de confesseur.","indice":"p5_badge"},"questions":[{"id":"q1","q":"Qu'est-ce que vous voulez ?","r":"Je relis les noms que j'ai notés hier. Je voudrais vérifier que chacun va bien. Lucas, Inès, Léo, Chloé...","indice":"p5_noms"}],"fin":{"demasque":"M. Perrin lève les yeux de son carnet. « Vous comprenez qu'on ne vous veut pas de mal. » Personne ne répond.","sansPreuve":"« Moi, flic ? » Il rit doucement. Sans preuve, les élèves le laissent finir sa liste.","rate":"M. Perrin a maintenant les prénoms, les visages et les rumeurs de quarante élèves."}},{"id":"duval","nom":"Mme Duval","zone":"entree","infiltre":true,"condition":{"rateLaVeille":"duval"},"grade":"Capitaine Duval, 41 ans","posture":"Même blazer beige, mêmes brochures, même sourire.","sprite":{"peau":"#f0c8a8","cheveux":"long","couleurCheveux":"#7a5a3a","haut":"#8a6a4a","accessoires":["lunettes"]},"observer":{"texte":"Même blazer beige, même cordon bleu à liseré blanc. Elle ne distribue plus rien : elle regarde les élèves qui arrivent.","indice":"d5_asso"},"questions":[{"id":"q1","q":"Vous êtes encore là ?","r":"Je suis venue vérifier que les lycéens vont bien. Un blocus à cette heure-là, c'est dangereux. Qui est responsable ?","indice":"d5_resp"}],"fin":{"demasque":"Mme Duval sourit : « Bien joué. » Elle laisse tomber sa pochette. À l'intérieur, la liste de leurs noms. Elle la reprend, puis part.","sansPreuve":"« Une association a le droit d'être là ! » Les adultes autour la soutiennent. Sans preuve, c'est toi qui es dehors.","rate":"Mme Duval a identifié la responsable du comité. Son nom est déjà sur un mandat."}}],"epilogue":{"parfait":"7h31. La grille tient. Il n'y a plus de flic parmi vous, ou presque. Trois lycées chantent la même chanson, et la voiture grise fait demi-tour et s'éloigne dans la rue.","moyen":"7h31. Le blocus tient, mais pas sans dégâts. Quelques noms circulent déjà dans un commissariat, et il y aura des suites.","mauvais":"7h31. La grille s'ouvre de l'intérieur. La police entre en force, des élèves sont arrêtés un à un, et Inès est emmenée la première. Ils savaient tout depuis lundi."},"epilogueFinal":{"victoire":"Vendredi, 7h30. La grille est bloquée. Trois lycées, quatre cents élèves, pas un nom sur une liste. Dans la voiture banalisée, le commissaire regarde sa montre. Ils ne disparaîtront pas, mais ils n'auront pas gagné cette semaine. Quelque part, une autre classe de lycéens lit ce que vous avez fait.","amer":"Le blocus a lieu, mais pas comme prévu. Quelques noms sont déjà dans des dossiers, quelques amitiés sont cassées. Lundi, les lycéens reviendront. Plus méfiants. Moins seuls ? Personne ne sait encore.","defaite":"Vendredi, la grille est vide. Chacun soupçonne chacun. Le commissaire n'a même pas eu besoin de descendre de la voiture : la méfiance a fait le travail à sa place."},"textesFin":{"bouton":"Passer à 7h30","boutonFini":"Il est 7h30 : le blocus commence","plusDeTemps":"Il est {heure}. Les grilles se ferment, le blocus commence.","titre":"Vendredi, 7h30"}}}};
